148				Function<? super Mono<Void>, ? extends Publisher<Void>> connectHook) {
149	
150			Assert.notNull(requestTimeout, "The requestTimeout can not be null");
151			Assert.notNull(transport, "The transport can not be null");
152			Assert.notNull(requestHandlers, "The requestHandlers can not be null");
153			Assert.notNull(notificationHandlers, "The notificationHandlers can not be null");
154	
155			this.requestTimeout = requestTimeout;
156			this.transport = transport;
157			// A response completes its caller only once the notifications that arrived before it
158			// have been handled: a prompt turn's updates come before its response.
159			this.outbound = new OutboundMessages(transport, requestTimeout, () -> this.connectFailure,
160					AcpClientSession::notConnected, "agent", this.notifications);
161			this.requestHandlers.putAll(requestHandlers);
162			this.notificationHandlers.putAll(notificationHandlers);
163	
164			logger.debug("AcpClientSession created with {} request handlers: {}",
165					requestHandlers.size(), requestHandlers.keySet());
166			logger.debug("AcpClientSession created with {} notification handlers: {}",
167					notificationHandlers.size(), notificationHandlers.keySet());
168	
169			// One shared daemon timer for every session in the JVM (see AcpSchedulers).
170			this.timeoutScheduler = AcpSchedulers.timeouts();
171	
172			// Serialize notification delivery: each notification's Mono completes before the next
173			// one starts, preserving arrival order even when handlers do async work. A response
174			// is released in its place among them (InboundOrder).
175			this.notificationSubscription = this.notifications
176				.drain(notification -> handleIncomingNotification(notification).onErrorComplete(t -> {
177					logger.error("Error handling notification: {}", t.getMessage());
178					return true;
179				}))
180				.doFinally(signal -> {
181					this.notifications.releaseHeld();
182					this.notificationDrainTerminated.tryEmitEmpty();
183				})
184				.subscribe(ignored -> {
185				}, error -> logger.warn("Notification delivery ended with an error", error));
186	
187			this.transport.connect(mono -> mono.doOnNext(this::handle).then(Mono.empty()))
188				.transform(connectHook)
189				.subscribe(v -> {
190				}, this::onConnectFailure);
191	
192			// A transport that refuses synchronously (stdio does, and every transport does when
193			// asked to connect twice) fails construction rather than handing back a session
194			// whose first request would time out.
195			Throwable failure = this.connectFailure;
196			if (failure != null) {
197				this.notifications.complete();
198				this.notificationSubscription.dispose();
199				// A refusal to connect at all (a reused transport) is a misuse, not a lost connection.
200				throw new IllegalStateException("ACP client transport is not connected: " + failure.getMessage(), failure);
201			}
202	
203			// When the transport later terminates (peer gone, stream failed for good), pending
204			// requests fail at once with the cause instead of waiting out the request timeout.
205			this.transport.awaitTermination().subscribe(v -> {
206			}, this::onTransportTerminated, () -> onTransportTerminated(null));
207		}
208	
209		private void onTransportTerminated(@Nullable Throwable cause) {
210			if (this.closing) {
211				return;
212			}
213			Throwable failure = cause != null ? cause : new IllegalStateException("ACP client transport terminated");
214			this.connectFailure = failure;
215			if (cause != null) {
216				logger.warn("ACP client transport terminated: {}", cause.getMessage());
217			}
218			else {
219				logger.debug("ACP client transport terminated by the peer");
220			}
221			dismissPendingResponses(failure);
222		}
223	
224		private void onConnectFailure(Throwable error) {
225			this.connectFailure = error;
226			logger.error("ACP client transport failed to connect; every request on this session will fail: {}",
227					error.getMessage());
228			dismissPendingResponses(error);
229		}
230	
231		private static AcpConnectionException notConnected(Throwable cause) {
232			return new AcpConnectionException("ACP client transport is not connected: " + cause.getMessage(), cause);
233		}
234	
235		private void dismissPendingResponses() {
236			dismissPendingResponses(null);
237		}
238	
239		private void dismissPendingResponses(@Nullable Throwable cause) {
240			this.outbound.dismissPending(cause);
241		}
242	
243		private void handle(AcpSchema.JSONRPCMessage message) {
244			if (message instanceof AcpSchema.JSONRPCResponse response) {
245				this.outbound.complete(response);
246			}
247			else if (message instanceof AcpSchema.JSONRPCRequest request) {
248				respondTo(request);
249			}
250			else if (message instanceof AcpSchema.JSONRPCNotification notification) {
251				if (AcpSchema.METHOD_CANCEL_REQUEST.equals(notification.method())) {
252					// Not queued behind the ordered notification drain: a slow session/update
253					// handler must not delay cancelling a pending request.
254					this.inbound.cancel(notification);
255				}
256				else {
257					enqueue(notification);
258				}
259			}
260			else {
261				logger.warn("Received unknown message type: {}", message.getClass().getName());
262			}
263		}
264	
265		/**
266		 * Answers a request from the agent; a failed handler is answered with an error response,
267		 * a request cancelled by $/cancel_request with -32800 unless it already answered. The
268		 * handler is called only once the notifications that arrived before the request have been
269		 * handled (InboundOrder), so a permission request follows the tool_call update before it;
270		 * the request is tracked from its arrival, so a $/cancel_request reaches it while it waits.
271		 */
272		private void respondTo(AcpSchema.JSONRPCRequest request) {
273			logger.debug("Received request method={} id={}", request.method(), request.id());
274			logger.trace("Incoming request method='{}' id={}", request.method(), request.id());
275			Mono<Void> inOrder = Mono.create(sink -> this.notifications.inOrder(sink::success));
276			this.inbound.track(request, inOrder.then(handleIncomingRequest(request)))
277				.onErrorResume(error -> Mono.just(InboundMessages.error(request, error)))
278				.flatMap(this.transport::sendMessage)
279				.onErrorComplete(t -> {
280					logger.warn("Issue sending response to the agent, ", t);
281					return true;
282				})
283				.subscribe();
284		}
285	
286		/** Queues a notification for in-order delivery by the notification drain. */
287		private void enqueue(AcpSchema.JSONRPCNotification notification) {
288			logger.debug("Received notification method={}", notification.method());
289			logger.trace("Incoming notification method='{}' params={}", notification.method(), notification.params());
290			Sinks.EmitResult result = this.notifications.offer(notification);
291			if (!result.isFailure()) {
292				return;
293			}
294			if (result == Sinks.EmitResult.FAIL_TERMINATED || result == Sinks.EmitResult.FAIL_CANCELLED
295					|| this.notifications.isCompleting()) {
296				// The session is shutting down. Refusing newly arriving notifications
297				// is the intended behaviour: a graceful shutdown stops accepting new
298				// work and drains what is already queued, and JSON-RPC notifications
299				// carry no delivery guarantee by design.
300				logger.debug("Session is closing; dropping notification method='{}' ({})", notification.method(),
301						result);
302			}
303			else {
304				// Overflow, no subscriber, or concurrent (non-serialized) emission:
305				// protocol traffic lost on a live session, which is never expected.
306				logger.error("Dropped notification method='{}': sink emission failed with {}", notification.method(),
307						result);
308			}
309		}
310	
311		/**
312		 * Handles an incoming JSON-RPC request by routing it to the appropriate handler.
313		 * @param request The incoming JSON-RPC request
314		 * @return A Mono containing the JSON-RPC response
315		 */
316		private Mono<AcpSchema.JSONRPCResponse> handleIncomingRequest(AcpSchema.JSONRPCRequest request) {
317			return Mono.defer(() -> {
318				var handler = this.requestHandlers.get(request.method());
319				if (handler == null) {
320					MethodNotFoundError error = getMethodNotFoundError(request.method());
321					logger.warn("No handler registered for request method '{}': {} - {}",
322							request.method(), error.message(),
323							error.data() != null ? error.data() : "register a handler to support this operation");
324					logger.trace("Available handlers: {}", this.requestHandlers.keySet());
325					return Mono.just(InboundMessages.error(request, AcpErrorCodes.METHOD_NOT_FOUND, error.message(),
326							error.data()));
327				}
328	
329				logger.debug("Invoking handler for method '{}'", request.method());
330				logger.trace("Handler params for '{}': {}", request.method(), request.params());
331				return InboundMessages.requireResult(HandlerFailures.invoke(() -> handler.handle(InboundMessages.paramsOrEmpty(request.params()))),
332						request.method())
333					.doOnSuccess(result -> logger.debug("Handler for '{}' completed successfully", request.method()))
334					.doOnError(error -> logger.debug("Handler for '{}' threw error: {}", request.method(), error.getMessage()))
335					.map(result -> InboundMessages.result(request, result));
336			});
337		}
338	
339		record MethodNotFoundError(String method, String message, @Nullable Object data) {
340		}
341	
342		private MethodNotFoundError getMethodNotFoundError(String method) {
343			// ACP-specific error messages for unsupported client methods
344			switch (method) {
345				case AcpSchema.METHOD_FS_READ_TEXT_FILE:
346					return new MethodNotFoundError(method, "File system read not supported",
347							Map.of("reason", "Client does not have fs.readTextFile capability"));
348				case AcpSchema.METHOD_FS_WRITE_TEXT_FILE:
349					return new MethodNotFoundError(method, "File system write not supported",
350							Map.of("reason", "Client does not have fs.writeTextFile capability"));
351				case AcpSchema.METHOD_SESSION_REQUEST_PERMISSION:
352					return new MethodNotFoundError(method, "Permission request not supported",
353							Map.of("reason", "No requestPermissionHandler registered - use --yolo flag or register a handler"));
354				case AcpSchema.METHOD_TERMINAL_CREATE:
355				case AcpSchema.METHOD_TERMINAL_OUTPUT:
356				case AcpSchema.METHOD_TERMINAL_RELEASE:
357				case AcpSchema.METHOD_TERMINAL_WAIT_FOR_EXIT:
358				case AcpSchema.METHOD_TERMINAL_KILL:
359					return new MethodNotFoundError(method, "Terminal not supported",
360							Map.of("reason", "Client does not have terminal capability"));
361				default:
362					return new MethodNotFoundError(method, "Method not found: " + method, null);
363			}
364		}
365	
366		/**
367		 * Handles an incoming JSON-RPC notification by routing it to the appropriate handler.
368		 * @param notification The incoming JSON-RPC notification
369		 * @return A Mono that completes when the notification is processed
370		 */
371		private Mono<Void> handleIncomingNotification(AcpSchema.JSONRPCNotification notification) {
372			return Mono.defer(() -> {
373				return InboundMessages.deliver(logger, notification, this.notificationHandlers, NotificationHandler::handle);
374			});
375		}
376	
377		/**
378		 * Sends a JSON-RPC request and returns the response.
379		 * @param <T> The expected response type
380		 * @param method The method name to call
381		 * @param requestParams The request parameters
382		 * @param typeRef Type reference for response deserialization
383		 * @return A Mono containing the response; an error response fails it with {@link AcpError}
384		 */
385		@Override
386		public <T> Mono<T> sendRequest(String method, Object requestParams, TypeRef<T> typeRef) {
387			return this.outbound.sendRequest(method, requestParams, typeRef);
388		}
389	
390		/**
391		 * Sends a JSON-RPC request with a timeout of its own instead of the session's request
392		 * timeout. The client sends {@code session/prompt} this way, since a prompt's answer comes
393		 * only at the end of its turn. When {@code timeout} passes, the request fails with a
394		 * {@link java.util.concurrent.TimeoutException} and the agent is sent a
395		 * {@code $/cancel_request}, as with the request timeout.
396		 * @param <T> The expected response type
397		 * @param method The method name to call
398		 * @param requestParams The request parameters
399		 * @param typeRef Type reference for response deserialization
400		 * @param timeout how long to wait for the response; {@code null} waits until it arrives, the
401		 * caller disposes the request, or the transport fails
402		 * @return A Mono containing the response; an error response fails it with {@link AcpError}
403		 */
404		public <T> Mono<T> sendRequest(String method, Object requestParams, TypeRef<T> typeRef,
405				@Nullable Duration timeout) {
406			return this.outbound.sendRequest(method, requestParams, typeRef, timeout);
407		}
408	
409		/**
410		 * Sends a JSON-RPC notification.
411		 * @param method The method name for the notification
412		 * @param params The notification parameters
413		 * @return A Mono that completes when the notification is sent
414		 */
415		@Override
416		public Mono<Void> sendNotification(String method, @Nullable Object params) {
417			return this.outbound.sendNotification(method, params);
418		}
419	
420		/**
421		 * Closes the session gracefully, allowing pending operations to complete.
422		 * @return A Mono that completes when the session is closed
423		 */
424		@Override
425		public Mono<Void> closeGracefully() {
426			return Mono.<Void>fromRunnable(() -> {
427				this.closing = true;
428				this.inbound.cancelAll();
429				dismissPendingResponses();
430				// Never lost to a notification being delivered concurrently (NotificationQueue).
431				this.notifications.complete();
432			})
433				// Wait for queued notifications to drain before tearing the session down;
434				// disposing immediately would discard them. Bounded so a handler that never
435				// completes cannot hang graceful close.
436				.then(this.notificationDrainTerminated.asMono()
437					.timeout(this.requestTimeout, Mono.empty(), this.timeoutScheduler))
438				.doFinally(signal -> {
439					notificationSubscription.dispose();
440				});
441		}
442	
443		/**
444		 * Closes the session immediately, potentially interrupting pending operations.
445		 */
446		@Override
447		public void close() {
448			this.closing = true;
449			this.inbound.cancelAll();
450			dismissPendingResponses();
451			this.notifications.complete();
452			notificationSubscription.dispose();
453			// A response held behind a notification still being handled completes now.
454			this.notifications.releaseHeld();
455		}
456	
457	}

