  3	 */
  4	
  5	package com.agentclientprotocol.sdk.spec;
  6	
  7	import java.util.Map;
  8	import java.util.function.BiFunction;
  9	import java.util.concurrent.CancellationException;
 10	
 11	import com.agentclientprotocol.sdk.error.AcpErrorCodes;
 12	import com.agentclientprotocol.sdk.error.AcpProtocolException;
 13	import com.agentclientprotocol.sdk.util.HandlerFailures;
 14	import org.jspecify.annotations.Nullable;
 15	import org.slf4j.Logger;
 16	import org.slf4j.LoggerFactory;
 17	import reactor.core.Exceptions;
 18	import reactor.core.publisher.Mono;
 19	
 20	/**
 21	 * How a session answers the requests and notifications its peer sends, the same way for
 22	 * both session sides.
 23	 */
 24	final class InboundMessages {
 25	
 26		private static final Logger LOGGER = LoggerFactory.getLogger(InboundMessages.class);
 27	
 28		/** The message of the internal error a handler's unexpected exception is answered with. */
 29		static final String INTERNAL_ERROR_MESSAGE = "Internal error";
 30	
 31		private InboundMessages() {
 32		}
 33	
 34		/**
 35		 * The params a handler receives. JSON-RPC lets a request or notification omit them;
 36		 * an omitted params reads as an empty object, which is what a peer sending {@code {}}
 37		 * would deliver, so handlers never see null.
 38		 */
 39		static Object paramsOrEmpty(@Nullable Object params) {
 40			return (params != null) ? params : Map.of();
 41		}
 42	
 43		/**
 44		 * Passes a notification to the handler registered for its method; a handler that fails
 45		 * (params it cannot read, say) is logged and skipped. One without a handler is ignored,
 46		 * logged by its method only: its params can carry personal data (agents send
 47		 * {@code _auth/status_update}, whose params carry the account's email address). An
 48		 * extension notification ({@code _}-prefixed) is logged at DEBUG, since ACP asks
 49		 * implementations to ignore notifications they do not recognize and a peer may send many;
 50		 * a protocol notification without a handler is logged at WARN, as it usually means a
 51		 * handler was not registered.
 52		 */
 53		static <H> Mono<Void> deliver(Logger logger, AcpSchema.JSONRPCNotification notification,
 54				Map<String, H> handlers, BiFunction<H, Object, Mono<Void>> handle) {
 55			H handler = handlers.get(notification.method());
 56			if (handler == null) {
 57				if (ExtensionMethods.isExtension(notification.method())) {
 58					logger.debug("No handler registered for extension notification method: {}", notification.method());
 59				}
 60				else {
 61					logger.warn("No handler registered for notification method: {}", notification.method());
 62				}
 63				return Mono.empty();
 64			}
 65			// A notification has no answer to carry a failure: it is logged (method and error
 66			// only) and the session reads on. A failure must not end the inbound stream. An Error
 67			// (HandlerFailures) is logged at ERROR with its stack trace.
 68			return HandlerFailures.invoke(() -> handle.apply(handler, paramsOrEmpty(notification.params())))
 69				.onErrorResume(error -> {
 70					Throwable failure = HandlerFailures.contain(error);
 71					if (failure instanceof HandlerFailures.HandlerError) {
 72						LOGGER.error("Notification {} handler failed with an error and was skipped",
 73								notification.method(), failure.getCause());
 74					}
 75					else if (error instanceof AcpError peerError) {
 76						// The peer's answer to a call the handler made: its message and data are the
 77						// peer's text, logged at DEBUG only.
 78						logger.warn("Notification {} failed and was skipped: the peer answered {} {}",
 79								notification.method(), peerError.getCode(), AcpErrorCodes.getDescription(peerError.getCode()));
 80						logger.debug("Notification {} failed: {}", notification.method(), peerError.toString());
 81					}
 82					else {
 83						logger.warn("Notification {} failed and was skipped: {}", notification.method(), error.toString());
 84					}
 85					return Mono.empty();
 86				});
 87		}
 88	
 89		/** A request always gets a response: a handler that completes empty is answered with an error. */
 90		static <T> Mono<T> requireResult(Mono<T> result, String method) {
 91			return result.switchIfEmpty(Mono.error(() -> new AcpProtocolException(AcpErrorCodes.INTERNAL_ERROR,
 92					"The " + method + " handler produced no response")));
 93		}
 94	
 95		static AcpSchema.JSONRPCResponse result(AcpSchema.JSONRPCRequest request, Object result) {
 96			return new AcpSchema.JSONRPCResponse(AcpSchema.JSONRPC_VERSION, request.id(), result, null);
 97		}
 98	
 99		static AcpSchema.JSONRPCResponse error(AcpSchema.JSONRPCRequest request, int code, String message,
100				@Nullable Object data) {
101			return new AcpSchema.JSONRPCResponse(AcpSchema.JSONRPC_VERSION, request.id(), null,
102					new AcpSchema.JSONRPCError(code, message, data));
103		}
104	
105		/**
106		 * The response to a request whose handling failed: an {@link AcpProtocolException} keeps
107		 * its code, message and data (it is the handler's intended answer), an {@link AcpError}
108		 * that escaped the handler passes on the error it carries unchanged, a cancellation
109		 * ({@link #isCancellation}) is the handler cancelling its own work (ACP v1 internal
110		 * cancellation: the same {@code -32800} as a cancel from the caller), anything else is an
111		 * internal error with the generic message {@value #INTERNAL_ERROR_MESSAGE}: an exception's
112		 * message can carry paths, queries or credentials the peer must not see, so it is logged
113		 * here, at WARN with its stack trace, and not sent. A handler that failed with an
114		 * {@link Error} ({@link HandlerFailures}) is answered with an internal error that names
115		 * the method and the error's type only, and the error is logged at ERROR with its stack
116		 * trace.
117		 */
118		static AcpSchema.JSONRPCResponse error(AcpSchema.JSONRPCRequest request, Throwable error) {
119			if (HandlerFailures.contain(error) instanceof HandlerFailures.HandlerError handlerError) {
120				Throwable cause = (handlerError.getCause() != null) ? handlerError.getCause() : handlerError;
121				LOGGER.error("The {} handler failed with {}; answered {} (Internal error)", request.method(),
122						cause.getClass().getName(), AcpErrorCodes.INTERNAL_ERROR, cause);
123				return error(request, AcpErrorCodes.INTERNAL_ERROR,
124						"Internal error in the " + request.method() + " handler (" + cause.getClass().getName() + ")",
125						null);
126			}
127			if (error instanceof AcpProtocolException protocolException) {
128				return new AcpSchema.JSONRPCResponse(AcpSchema.JSONRPC_VERSION, request.id(), null,
129						AcpSchema.JSONRPCError.from(protocolException));
130			}
131			if (error instanceof AcpError peerError) {
132				// A request the handler made failed and the handler let it escape: the peer's
133				// error is passed on as it is, code, message and data.
134				LOGGER.debug("The {} handler let a peer error escape; passed on {}", request.method(), peerError.getCode());
135				return new AcpSchema.JSONRPCResponse(AcpSchema.JSONRPC_VERSION, request.id(), null, peerError.getError());
136			}
137			if (isCancellation(error)) {
138				String message = error.getMessage();
139				return error(request, AcpErrorCodes.REQUEST_CANCELLED,
140						(message != null) ? message : InboundRequests.CANCELLED_MESSAGE, null);
141			}
142			LOGGER.warn("The {} handler failed; answered {} ({})", request.method(), AcpErrorCodes.INTERNAL_ERROR,
143					INTERNAL_ERROR_MESSAGE, error);
144			return error(request, AcpErrorCodes.INTERNAL_ERROR, INTERNAL_ERROR_MESSAGE, null);
145		}
146	
147		/**
148		 * Whether a handler's failure means its work was cancelled: a
149		 * {@link CancellationException} or an interrupt (Reactor's {@code block()} wraps it), or
150		 * an {@link AcpProtocolException} with code -32800.
151		 */
152		static boolean isCancellation(Throwable error) {
153			Throwable unwrapped = Exceptions.unwrap(error);
154			return unwrapped instanceof CancellationException || unwrapped instanceof InterruptedException
155					|| (error instanceof AcpProtocolException protocolException
156							&& protocolException.getCode() == AcpErrorCodes.REQUEST_CANCELLED);
157		}
158	
159	}
160	/*
161	 * Copyright 2025-2026 the original author or authors.
162	 */
163	
164	package com.agentclientprotocol.sdk.spec;
165	
166	import java.math.BigInteger;
167	import java.util.Map;
168	import java.util.concurrent.ConcurrentHashMap;
169	import java.util.function.Supplier;
170	
171	import com.agentclientprotocol.sdk.error.AcpErrorCodes;
172	import org.jspecify.annotations.Nullable;
173	import org.slf4j.Logger;
174	import org.slf4j.LoggerFactory;
175	import reactor.core.publisher.Mono;
176	import reactor.core.publisher.Sinks;
177	
178	/**
179	 * The requests a session received from its peer and has not answered yet, keyed by request
180	 * id, so that a {@code $/cancel_request} can cancel one (ACP v1, Cancellation), the same way
181	 * for both session sides.
182	 *
183	 * <p>
184	 * A cancelled request still gets exactly one response: the handler's, when it came first,
185	 * otherwise the error {@code -32800} (Request cancelled). Both race inside one {@code Mono}
186	 * ({@link Mono#takeUntilOther}), which signals at most once, so there is never a second
187	 * response for the id. The handler's subscription is cancelled, which also cancels the
188	 * requests it was waiting on (their sessions send {@code $/cancel_request} in turn).
189	 * </p>
190	 */
191	final class InboundRequests {
192	
193		private static final Logger logger = LoggerFactory.getLogger(InboundRequests.class);
194	
195		static final String CANCELLED_MESSAGE = "Request cancelled";
196	
197		/** The cancel trigger of each request being handled, keyed by its normalised id. */
198		private final ConcurrentHashMap<Object, Cancel> inFlight = new ConcurrentHashMap<>();
199	
200		/** One request's cancel: the trigger, and whether a cancel has been asked for. */
201		private static final class Cancel {
202	
203			final Sinks.Empty<Void> trigger = Sinks.empty();
204	
205			volatile boolean requested;
206	
207			boolean fire() {
208				this.requested = true;
209				return this.trigger.tryEmitEmpty().isSuccess();
210			}
211	
212		}
213	
214		/** Set once the session closes: requests still arriving are cancelled at once. */
215		private volatile boolean closed;
216	
217		/**
218		 * Makes {@code response}, the answer to {@code request}, cancellable by
219		 * {@link #cancel}, which answers {@code -32800}. See
220		 * {@link #track(AcpSchema.JSONRPCRequest, Mono, Supplier)}.
221		 */
222		Mono<AcpSchema.JSONRPCResponse> track(AcpSchema.JSONRPCRequest request, Mono<AcpSchema.JSONRPCResponse> response) {
223			return track(request, response, () -> cancelled(request));
224		}
225	
226		/**
227		 * Makes {@code response}, the answer to {@code request}, cancellable by
228		 * {@link #cancel}. Call it on the complete answer: whatever {@code response} emits is the
229		 * request's only response, and when a cancel wins the race, {@code whenCancelled}
230		 * supplies the response instead. A request without an id cannot be cancelled and is
231		 * passed through.
232		 *
233		 * <p>
234		 * The request becomes cancellable only once {@code response} is subscribed, so a cancel
235		 * always cancels a running handler (whose own cancellation, a prompt's turn included,
236		 * runs before the answer is produced), and stops being cancellable as soon as its
237		 * response is produced.
238		 * </p>
239		 */
240		Mono<AcpSchema.JSONRPCResponse> track(AcpSchema.JSONRPCRequest request, Mono<AcpSchema.JSONRPCResponse> response,
241				Supplier<AcpSchema.JSONRPCResponse> whenCancelled) {
242			Object key = key(request.id());
243			if (key == null) {
244				return response;
245			}
246			return Mono.defer(() -> {
247				Cancel cancel = new Cancel();
248				// takeUntilOther subscribes the trigger before the response, and passes
249				// onSubscribe down only once the response is subscribed: registering here means
250				// a cancel can only reach a handler that is running. A handler that fails once
251				// it is cancelled (an interrupted blocking handler throws) was cancelled too.
252				return response.onErrorResume(error -> cancel.requested, error -> Mono.empty())
253					.takeUntilOther(cancel.trigger.asMono())
254					.doOnSubscribe(subscription -> register(key, cancel, request))
255					.switchIfEmpty(Mono.fromSupplier(whenCancelled))
256					.doOnNext(answer -> this.inFlight.remove(key, cancel))
257					.doFinally(signal -> this.inFlight.remove(key, cancel));
258			});
259		}
260	
261		private void register(Object key, Cancel cancel, AcpSchema.JSONRPCRequest request) {
262			if (this.closed) {
263				cancel.fire();
264				return;
265			}
266			if (this.inFlight.putIfAbsent(key, cancel) != null) {
267				// The peer reused the id of a request still being handled: a cancel names the
268				// first one.
269				logger.warn("Request id {} is already in use by an unanswered request", request.id());
270			}
271			else if (this.closed) {
272				// Closed while registering: cancelAll may not have seen this request.
273				cancel.fire();
274			}
275		}
276	
277		/**
278		 * Cancels the request with this id, if it is still being handled.
279		 * @return whether a request was cancelled; false when the id is unknown or already
280		 * answered
281		 */
282		boolean cancel(@Nullable Object requestId) {
283			Object key = key(requestId);
284			Cancel cancel = (key != null) ? this.inFlight.get(key) : null;
285			if (cancel == null || !cancel.fire()) {
286				logger.debug("Ignored $/cancel_request for id {}: no request with that id is being handled", requestId);
287				return false;
288			}
289			logger.debug("Cancelled request {}", requestId);
290			return true;
291		}
292	
293		/**
294		 * Cancels every request being handled, and every request that arrives after: the session
295		 * is closing (ACP v1 internal cancellation). Each is answered as if the peer had
296		 * cancelled it, so far as the transport still delivers.
297		 */
298		void cancelAll() {
299			this.closed = true;
300			for (Object key : this.inFlight.keySet()) {
301				cancel(key);
302			}
303		}
304	
305		/**
306		 * Cancels the request a {@code $/cancel_request} notification names. The params are read
307		 * here rather than through {@link AcpTransport#unmarshalParams}: a notification has no
308		 * response to carry a -32602, so params without a usable {@code requestId} (missing, null,
309		 * or not a string or integer, as the schema's {@code RequestId} requires) are logged and
310		 * ignored.
311		 */
312		boolean cancel(AcpSchema.JSONRPCNotification notification) {
313			Object requestId = requestId(notification.params());
314			if (!isRequestId(requestId)) {
315				logger.debug("Ignored $/cancel_request with invalid params {}", notification.params());
316				return false;
317			}
318			return cancel(requestId);
319		}
320	
321		/** The number of requests being handled. */
322		int size() {
323			return this.inFlight.size();
324		}
325	
326		static AcpSchema.JSONRPCResponse cancelled(AcpSchema.JSONRPCRequest request) {
327			return InboundMessages.error(request, AcpErrorCodes.REQUEST_CANCELLED, CANCELLED_MESSAGE, null);
328		}
329	
330		/**
331		 * The id a {@code $/cancel_request} names. Its params arrive as a map from the JSON
332		 * transports and as the typed record from in-process ones.
333		 */
334		private static @Nullable Object requestId(@Nullable Object params) {
335			if (params instanceof AcpSchema.CancelRequestNotification notification) {
336				return notification.requestId();
337			}
338			if (params instanceof Map<?, ?> map) {
339				return map.get("requestId");
340			}
341			return null;
342		}
343	
344		/** A JSON-RPC id the schema allows and a request can carry: a string or an integer. */
345		private static boolean isRequestId(@Nullable Object id) {
346			return id instanceof String || id instanceof Integer || id instanceof Long || id instanceof Short
347					|| id instanceof Byte || (id instanceof BigInteger big && big.bitLength() < Long.SIZE);
348		}
349	
350		/**
351		 * The table key of a JSON-RPC id. An integer id may be read as an Integer in one message
352		 * and a Long in another, so integer types compare by value; a string id never equals a
353		 * number, and a fractional or out-of-range number is kept as it is. A null id cannot be
354		 * correlated.
355		 */
356		static @Nullable Object key(@Nullable Object id) {
357			if (id instanceof Integer || id instanceof Long || id instanceof Short || id instanceof Byte) {
358				return ((Number) id).longValue();
359			}
360			if (id instanceof BigInteger big && big.bitLength() < Long.SIZE) {
361				return big.longValue();
362			}
363			return id;
364		}
365	
366	}
