371	package com.agentclientprotocol.sdk.spec;
372	
373	import java.time.Duration;
374	import java.util.UUID;
375	import java.util.concurrent.atomic.AtomicBoolean;
376	import java.util.concurrent.atomic.AtomicLong;
377	import java.util.function.Function;
378	import java.util.function.Supplier;
379	
380	import com.agentclientprotocol.sdk.json.TypeRef;
381	import com.agentclientprotocol.sdk.util.AcpSchedulers;
382	import org.jspecify.annotations.Nullable;
383	import org.reactivestreams.Publisher;
384	import org.slf4j.Logger;
385	import org.slf4j.LoggerFactory;
386	import reactor.core.Disposable;
387	import reactor.core.Disposables;
388	import reactor.core.publisher.Flux;
389	import reactor.core.publisher.Mono;
390	import reactor.core.publisher.Sinks;
391	import reactor.core.publisher.SynchronousSink;
392	
393	/**
394	 * The requests and notifications a session sends to its peer, the same way for both session
395	 * sides: request ids, the requests still waiting for a response, the request timeout, and
396	 * failing fast once the transport can no longer deliver.
397	 */
398	final class OutboundMessages {
399	
400		private static final Logger logger = LoggerFactory.getLogger(OutboundMessages.class);
401	
402		private final AcpTransport transport;
403	
404		private final Duration requestTimeout;
405	
406		/** The reason the transport cannot deliver (it failed to connect or start, or terminated), or null. */
407		private final Supplier<@Nullable Throwable> transportFailure;
408	
409		/** Wraps the transport failure into the error a caller receives. */
410		private final Function<Throwable, RuntimeException> unavailable;
411	
412		/** Requests waiting for a response, keyed by request id. */
413		private final PendingResponses pendingResponses;
414	
415		/** When a response that arrived may complete its caller. */
416		private final ResponseOrder responseOrder;
417	
418		/** Session-specific prefix for request ids. */
419		private final String idPrefix = UUID.randomUUID().toString().substring(0, 8);
420	
421		private final AtomicLong requestCounter = new AtomicLong(0);
422	
423		OutboundMessages(AcpTransport transport, Duration requestTimeout, Supplier<@Nullable Throwable> transportFailure,
424				Function<Throwable, RuntimeException> unavailable, String peer) {
425			this(transport, requestTimeout, transportFailure, unavailable, peer, ResponseOrder.IMMEDIATE);
426		}
427	
428		OutboundMessages(AcpTransport transport, Duration requestTimeout, Supplier<@Nullable Throwable> transportFailure,
429				Function<Throwable, RuntimeException> unavailable, String peer, ResponseOrder responseOrder) {
430			this.transport = transport;
431			this.responseOrder = responseOrder;
432			this.requestTimeout = requestTimeout;
433			this.transportFailure = transportFailure;
434			this.unavailable = unavailable;
435			this.pendingResponses = new PendingResponses(transportFailure, unavailable, peer);
436		}
437	
438		/**
439		 * Sends a request and waits, at most the request timeout, for its response. An error
440		 * response fails the returned Mono with {@link AcpError}. A response that arrived
441		 * completes the Mono when the {@link ResponseOrder} lets it, within the same timeout.
442		 */
443		<T> Mono<T> sendRequest(String method, Object params, TypeRef<T> typeRef) {
444			return sendRequest(method, params, typeRef, this.requestTimeout);
445		}
446	
447		/**
448		 * Sends a request and waits, at most {@code timeout}, for its response; with a null
449		 * {@code timeout} it waits until the response arrives, the caller disposes the request, or
450		 * the transport fails. Otherwise as {@link #sendRequest(String, Object, TypeRef)}.
451		 */
452		<T> Mono<T> sendRequest(String method, Object params, TypeRef<T> typeRef, @Nullable Duration timeout) {
453			Mono<AcpSchema.JSONRPCResponse> response = Mono.deferContextual(ctx -> {
454				// One id per subscription: a resubscribed request (a retry) is a new request.
455				String requestId = this.idPrefix + "-" + this.requestCounter.getAndIncrement();
456				long sentAt = this.responseOrder.position();
457				Runnable answered = this.responseOrder.awaiting(sentAt);
458				// Completes once the request is handed to the transport; a $/cancel_request
459				// waits for it, so it never overtakes its request on an ordered transport.
460				Sinks.Empty<Void> written = Sinks.empty();
461				// At most one $/cancel_request per request, whether the caller disposed it or a
462				// RequestCancellation trigger fired.
463				AtomicBoolean cancelSent = new AtomicBoolean();
464				Runnable cancel = () -> {
465					if (cancelSent.compareAndSet(false, true)) {
466						cancelRequest(requestId, written.asMono());
467					}
468				};
469				Disposable.Swap gracefulCancel = Disposables.swap();
470				return Mono.<AcpSchema.JSONRPCResponse>create(responseSink -> {
471					if (!this.pendingResponses.register(requestId, responseSink, cancel)) {
472						return;
473					}
474					logger.debug("Sending request for method {} with id {}", method, requestId);
475					logger.trace("Outgoing request method='{}' id={} params={}", method, requestId, params);
476					AcpSchema.JSONRPCRequest request = new AcpSchema.JSONRPCRequest(AcpSchema.JSONRPC_VERSION, requestId,
477							method, params);
478					this.transport.sendMessage(request).contextWrite(ctx).subscribe(v -> {
479					}, error -> {
480						written.tryEmitError(error);
481						this.pendingResponses.abandon(requestId, responseSink);
482						responseSink.error(error);
483					}, written::tryEmitEmpty);
484					Object trigger = ctx.getOrDefault(RequestCancellation.KEY, null);
485					if (trigger instanceof Publisher<?> publisher) {
486						gracefulCancel.update(cancelOn(publisher, requestId, cancel));
487					}
488				}).doFinally(signal -> {
489					gracefulCancel.dispose();
490					answered.run();
491				})
492					.flatMap(answer -> this.responseOrder.after(sentAt, answer));
493			});
494			return withTimeout(response, timeout)
495				.handle((answer, resultSink) -> deliver(method, answer, typeRef, resultSink));
496		}
497	
498		private static <R> Mono<R> withTimeout(Mono<R> response, @Nullable Duration timeout) {
499			return (timeout != null) ? AcpSchedulers.withTimeout(response, timeout) : response;
500		}
501	
502		/** Runs {@code cancel} when a RequestCancellation trigger fires while the request still waits. */
503		private Disposable cancelOn(Publisher<?> trigger, String requestId, Runnable cancel) {
504			return Flux.from(trigger).take(1).then().subscribe(v -> {
505			}, error -> logger.debug("Ignored a failed cancel trigger for request {}", requestId), () -> {
506				if (this.pendingResponses.isPending(requestId)) {
507					cancel.run();
508				}
509			});
510		}
511	
512		private <T> void deliver(String method, AcpSchema.JSONRPCResponse response, TypeRef<T> typeRef,
513				SynchronousSink<T> resultSink) {
514			AcpSchema.JSONRPCError error = response.error();
515			if (error != null) {
516				// The caller's failure is the report; the error's data is the peer's payload.
517				logger.debug("Request {} failed with peer error {}", method, error.code());
518				resultSink.error(new AcpError(error));
519			}
520			else if (typeRef.getType().equals(Void.class)) {
521				resultSink.complete();
522			}
523			else {
524				ResponseResults.deliver(method, response.result(), typeRef, this.transport, resultSink);
525			}
526		}
527	
528		/**
529		 * Tells the peer that the caller gave up on a request (ACP v1 {@code $/cancel_request}):
530		 * its subscription was cancelled, by the caller or by its timeout, before a response.
531		 * Sent once the request itself has been handed to the transport, and not at all if that
532		 * failed. Fire and forget: the transport may be why the caller gave up.
533		 */
534		private void cancelRequest(String requestId, Mono<Void> written) {
535			written.then(sendNotification(AcpSchema.METHOD_CANCEL_REQUEST, new AcpSchema.CancelRequestNotification(requestId)))
536				// Off the thread that cancelled, which may be the shared timeout timer: the
537				// transport's emission can wait for a busy outbound sink.
538				.subscribeOn(AcpSchedulers.timeoutDelivery())
539				.subscribe(v -> {
540				}, error -> logger.debug("No $/cancel_request sent for id {}: {}", requestId, error.getMessage()),
541						() -> logger.debug("Sent $/cancel_request for id {}", requestId));
542		}
543	
544		/** Sends a notification, or fails at once when the transport cannot deliver. */
545		Mono<Void> sendNotification(String method, @Nullable Object params) {
546			return Mono.defer(() -> {
547				Throwable failure = this.transportFailure.get();
548				if (failure != null) {
549					return Mono.error(this.unavailable.apply(failure));
550				}
551				return this.transport
552					.sendMessage(new AcpSchema.JSONRPCNotification(AcpSchema.JSONRPC_VERSION, method, params));
553			});
554		}
555	
556		/** Completes the request this response answers. */
557		void complete(AcpSchema.JSONRPCResponse response) {
558			this.pendingResponses.complete(response);
559		}
560	
561		/** Fails every request still waiting for a response. */
562		void dismissPending(@Nullable Throwable cause) {
563			this.pendingResponses.dismissAll(cause);
564		}
565	
566		/** The number of requests waiting for a response. */
567		int pendingRequests() {
568			return this.pendingResponses.size();
569		}
570	
571	}

