  4	
  5	package com.agentclientprotocol.sdk.spec;
  6	
  7	import java.time.Duration;
  8	import java.util.Map;
  9	import java.util.Set;
 10	import java.util.function.BooleanSupplier;
 11	import java.util.function.Function;
 12	import java.util.concurrent.ConcurrentHashMap;
 13	import java.util.concurrent.atomic.AtomicReference;
 14	
 15	
 16	import com.agentclientprotocol.sdk.error.AcpConnectionException;
 17	import com.agentclientprotocol.sdk.error.AcpErrorCodes;
 18	import com.agentclientprotocol.sdk.util.AcpSchedulers;
 19	import com.agentclientprotocol.sdk.util.Assert;
 20	import com.agentclientprotocol.sdk.util.HandlerFailures;
 21	import com.agentclientprotocol.sdk.json.TypeRef;
 22	import org.jspecify.annotations.Nullable;
 23	import org.slf4j.Logger;
 24	import org.slf4j.LoggerFactory;
 25	import reactor.core.publisher.Mono;
 26	
 27	/**
 28	 * Agent-side implementation of the ACP (Agent Client Protocol) session that manages
 29	 * bidirectional JSON-RPC communication between agents and clients. This is the agent-side
 30	 * counterpart to {@link AcpClientSession}.
 31	 *
 32	 * <p>
 33	 * The session manages:
 34	 * <ul>
 35	 * <li>Request/response handling with unique message IDs</li>
 36	 * <li>Notification processing</li>
 37	 * <li>Message timeout management</li>
 38	 * <li>Transport layer abstraction</li>
 39	 * <li>Single-turn enforcement (only one prompt active at a time per session; a turn ends
 40	 * with its prompt's response, also after {@code session/cancel})</li>
 41	 * </ul>
 42	 *
 43	 * <p>
 44	 * This is the agent-side session that receives requests from clients (initialize,
 45	 * newSession, prompt, etc.) and sends requests to clients (readTextFile, writeTextFile,
 46	 * requestPermission, etc.)
 47	 * </p>
 48	 *
 49	 * @author Mark Pollack
 50	 */
 51	public class AcpAgentSession implements AcpSession {
 52	
 53		private static final Logger logger = LoggerFactory.getLogger(AcpAgentSession.class);
 54	
 55		/** Transport layer implementation for message exchange */
 56		private final AcpAgentTransport transport;
 57	
 58		/** Requests and notifications sent to the client, and the requests waiting for a response */
 59		private final OutboundMessages outbound;
 60	
 61		/** Map of request handlers keyed by method name */
 62		private final ConcurrentHashMap<String, RequestHandler<?>> requestHandlers = new ConcurrentHashMap<>();
 63	
 64		/** Map of notification handlers keyed by method name */
 65		private final ConcurrentHashMap<String, NotificationHandler> notificationHandlers = new ConcurrentHashMap<>();
 66	
 67		/** Requests from the client still being handled, which a $/cancel_request can cancel */
 68		private final InboundRequests inbound = new InboundRequests();
 69	
 70		/** Single-turn enforcement: the active prompt of each logical ACP sessionId. */
 71		private final ActivePrompts activePrompts = new ActivePrompts();
 72	
 73		/** The cancel grace period and maximum prompt duration of each prompt. */
 74		private final PromptDeadlines promptDeadlines;
 75	
 76		/**
 77		 * Set when the transport's {@code start()} fails (already started, port in use, ...).
 78		 * Requests to the client are then failed immediately with the cause.
 79		 */
 80		private volatile @Nullable Throwable startFailure;
 81	
 82		/**
 83		 * Functional interface for handling incoming JSON-RPC requests. Implementations
 84		 * should process the request parameters and return a response.
 85		 *
 86		 * @param <T> Response type
 87		 */
 88		@FunctionalInterface
 89		public interface RequestHandler<T> {
 90	
 91			/**
 92			 * Handles an incoming request with the given parameters.
 93			 * @param params The request parameters; an omitted params arrives as an empty
 94			 * object
 95			 * @return A Mono containing the response object; it must not complete empty
 96			 */
 97			Mono<T> handle(Object params);
 98	
 99		}
100	
101		/**
102		 * Functional interface for handling incoming JSON-RPC notifications. Implementations
103		 * should process the notification parameters without returning a response.
104		 */
105		@FunctionalInterface
106		public interface NotificationHandler {
107	
108			/**
109			 * Handles an incoming notification with the given parameters.
110			 * @param params The notification parameters; an omitted params arrives as an empty
111			 * object
112			 * @return A Mono that completes when the notification is processed
113			 */
114			Mono<Void> handle(Object params);
115	
116		}
117	
118		/**
119		 * Creates a new AcpAgentSession with the specified configuration and handlers, and the
120		 * default prompt timeouts ({@link PromptTimeouts#DEFAULTS}).
121		 * @param requestTimeout Duration to wait for responses
122		 * @param transport Transport implementation for message exchange
123		 * @param requestHandlers Map of method names to request handlers
124		 * @param notificationHandlers Map of method names to notification handlers
125		 */
126		public AcpAgentSession(Duration requestTimeout, AcpAgentTransport transport,
127				Map<String, RequestHandler<?>> requestHandlers, Map<String, NotificationHandler> notificationHandlers) {
128			this(requestTimeout, transport, requestHandlers, notificationHandlers, PromptTimeouts.DEFAULTS);
129		}
130	
131		/**
132		 * Creates a new AcpAgentSession with the specified configuration and handlers.
133		 * @param requestTimeout Duration to wait for responses
134		 * @param transport Transport implementation for message exchange
135		 * @param requestHandlers Map of method names to request handlers
136		 * @param notificationHandlers Map of method names to notification handlers
137		 * @param promptTimeouts when the session answers a prompt its handler has not: the cancel
138		 * grace period and the maximum prompt duration
139		 */
140		public AcpAgentSession(Duration requestTimeout, AcpAgentTransport transport,
141				Map<String, RequestHandler<?>> requestHandlers, Map<String, NotificationHandler> notificationHandlers,
142				PromptTimeouts promptTimeouts) {
143			this(requestTimeout, transport, requestHandlers, notificationHandlers, promptTimeouts, AcpSchedulers::after);
144		}
145	
146		/** As above, with the timer the prompt deadlines run on (a virtual-time one in tests). */
147		AcpAgentSession(Duration requestTimeout, AcpAgentTransport transport,
148				Map<String, RequestHandler<?>> requestHandlers, Map<String, NotificationHandler> notificationHandlers,
149				PromptTimeouts promptTimeouts, Function<Duration, Mono<?>> timer) {
150	
151			Assert.notNull(requestTimeout, "The requestTimeout can not be null");
152			Assert.notNull(promptTimeouts, "The promptTimeouts can not be null");
153			Assert.notNull(transport, "The transport can not be null");
154			Assert.notNull(requestHandlers, "The requestHandlers can not be null");
155			Assert.notNull(notificationHandlers, "The notificationHandlers can not be null");
156	
157			this.transport = transport;
158			this.promptDeadlines = new PromptDeadlines(promptTimeouts, timer);
159			this.outbound = new OutboundMessages(transport, requestTimeout, () -> this.startFailure,
160					AcpAgentSession::notStarted, "client");
161			this.requestHandlers.putAll(requestHandlers);
162			this.notificationHandlers.putAll(notificationHandlers);
163	
164			this.transport.start(mono -> mono.flatMap(this::handle)).subscribe(v -> {
165			}, this::onStartFailure);
166	
167			// A transport that refuses synchronously (every transport does when asked to start
168			// twice) fails construction rather than handing back a session that can never talk.
169			Throwable failure = this.startFailure;
170			if (failure != null) {
171				// A refusal to start at all (a reused transport) is a misuse, not a lost connection.
172				throw new IllegalStateException("ACP agent transport is not started: " + failure.getMessage(), failure);
173			}
174		}
175	
176		private void onStartFailure(Throwable error) {
177			this.startFailure = error;
178			logger.error("ACP agent transport failed to start; every request on this session will fail: {}",
179					error.getMessage());
180			dismissPendingResponses(error);
181		}
182	
183		private static AcpConnectionException notStarted(Throwable cause) {
184			return new AcpConnectionException("ACP agent transport is not started: " + cause.getMessage(), cause);
185		}
186	
187		private void dismissPendingResponses() {
188			dismissPendingResponses(null);
189		}
190	
191		private void dismissPendingResponses(@Nullable Throwable cause) {
192			this.outbound.dismissPending(cause);
193		}
194	
195		/**
196		 * Handles an incoming JSON-RPC message and returns an optional response message.
197		 * @param message The incoming message
198		 * @return A Mono containing the response message, or empty for notifications
199		 */
200		private Mono<AcpSchema.JSONRPCMessage> handle(AcpSchema.JSONRPCMessage message) {
201			if (message instanceof AcpSchema.JSONRPCResponse response) {
202				this.outbound.complete(response);
203				return Mono.empty();
204			}
205			if (message instanceof AcpSchema.JSONRPCRequest request) {
206				logger.debug("Received request method={} id={}", request.method(), request.id());
207				// Mono.from widens the response Mono to the message type without an operator.
208				// The whole answer is tracked, so a $/cancel_request races it inside one Mono.
209				AtomicReference<ActivePrompts.@Nullable Turn> promptTurn = new AtomicReference<>();
210				return Mono.from(this.inbound
211					.track(request, handleIncomingRequest(request, promptTurn),
212							() -> whenCancelled(request, promptTurn.get()))
213					.onErrorResume(error -> Mono.just(InboundMessages.error(request, error))));
214			}
215			if (message instanceof AcpSchema.JSONRPCNotification notification) {
216				logger.debug("Received notification method={}", notification.method());
217				return handleIncomingNotification(notification).then(Mono.empty());
218			}
219			logger.warn("Received unknown message type: {}", message.getClass().getName());
220			return Mono.empty();
221		}
222	
223		/**
224		 * Handles an incoming JSON-RPC request by routing it to the appropriate handler.
225		 * For session/prompt requests, enforces single-turn semantics.
226		 * @param request The incoming JSON-RPC request
227		 * @return A Mono containing the JSON-RPC response
228		 */
229		private Mono<AcpSchema.JSONRPCResponse> handleIncomingRequest(AcpSchema.JSONRPCRequest request,
230				AtomicReference<ActivePrompts.@Nullable Turn> promptTurn) {
231			return Mono.defer(() -> {
232				var handler = this.requestHandlers.get(request.method());
233				if (handler == null) {
234					MethodNotFoundError error = getMethodNotFoundError(request.method());
235					return Mono.just(InboundMessages.error(request, AcpErrorCodes.METHOD_NOT_FOUND, error.message(),
236							error.data()));
237				}
238	
239				// Single-turn enforcement for session/prompt requests
240				if (AcpSchema.METHOD_SESSION_PROMPT.equals(request.method())) {
241					String sessionId = extractSessionId(request.params());
242					ActivePrompts.Turn turn = activePrompts.tryStart(sessionId, request.id());
243					if (turn == null) {
244						// -32600, not -32000: ACP v1 defines -32000 as "Authentication required".
245						return Mono.just(InboundMessages.error(request, AcpErrorCodes.INVALID_REQUEST,
246								"There is already an active prompt on session " + sessionId,
247								Map.of("sessionId", sessionId)));
248					}
249					promptTurn.set(turn);
250	
251					// The turn ends before the response is published (#14): see
252					// ActivePrompts.endBeforePublishing. Mono.defer keeps a handler that throws
253					// synchronously from holding the turn forever: the throw becomes an error
254					// signal that passes through the release.
255					// The deadlines may answer instead of the handler; either answer passes
256					// through the release.
257					// Once session/cancel was received, the prompt answers stop reason cancelled,
258					// whatever its handler returns or fails with (ACP v1, prompt turn, Cancellation).
259					return activePrompts.endBeforePublishing(turn, promptDeadlines.answer(turn, request,
260							InboundMessages.requireResult(HandlerFailures.invoke(() -> handler.handle(InboundMessages.paramsOrEmpty(request.params()))),
261									request.method())
262								.map(result -> InboundMessages.result(request, cancelledIfCancelling(turn, request, result)))
263								.onErrorResume(error -> turn.answer().isCancelling(),
264										error -> Mono.just(cancelledPromptAfterFailure(request, error)))));
265				}
266	
267				Mono<AcpSchema.JSONRPCResponse> response = InboundMessages
268					.requireResult(HandlerFailures.invoke(() -> handler.handle(InboundMessages.paramsOrEmpty(request.params()))),
269							request.method())
270					.map(result -> InboundMessages.result(request, result));
271				if (AcpSchema.METHOD_SESSION_CLOSE.equals(request.method())) {
272					return cancelOngoingWork(extractSessionId(request.params())).then(response);
273				}
274				return response;
275			});
276		}
277	
278		/**
279		 * Cancels a closing session's ongoing work as if session/cancel had been received (ACP
280		 * v1, CloseSessionRequest: the agent must cancel any ongoing work related to the
281		 * session, treating it as if session/cancel was called, and then free its resources):
282		 * the session/cancel handler is told, and an active prompt is cancelled and answers
283		 * cancelled. Completes once that prompt's turn has ended, so the close handler frees
284		 * the session after its work has stopped.
285		 */
286		private Mono<Void> cancelOngoingWork(String sessionId) {
287			ActivePrompts.Turn turn = this.activePrompts.current(sessionId);
288			this.activePrompts.cancel(sessionId);
289			Mono<Void> cancelHandler = Mono.empty();
290			if (this.notificationHandlers.containsKey(AcpSchema.METHOD_SESSION_CANCEL)) {
291				cancelHandler = InboundMessages.deliver(logger,
292						new AcpSchema.JSONRPCNotification(AcpSchema.JSONRPC_VERSION, AcpSchema.METHOD_SESSION_CANCEL,
293								Map.of("sessionId", sessionId)),
294						this.notificationHandlers, NotificationHandler::handle);
295			}
296			return turn == null ? cancelHandler : cancelHandler.then(turn.ended());
297		}
298	
299		/**
300		 * The answer to a request a $/cancel_request cancelled: -32800, except for a prompt
301		 * already cancelled by session/cancel, which must answer stop reason cancelled (ACP v1,
302		 * prompt turn, Cancellation).
303		 */
304		private static AcpSchema.JSONRPCResponse whenCancelled(AcpSchema.JSONRPCRequest request,
305				ActivePrompts.@Nullable Turn promptTurn) {
306			if (promptTurn != null && promptTurn.answer().isCancelling()) {
307				return cancelledPrompt(request);
308			}
309			return InboundRequests.cancelled(request);
310		}
311	
312		private static AcpSchema.JSONRPCResponse cancelledPrompt(AcpSchema.JSONRPCRequest request) {
313			return InboundMessages.result(request, new AcpSchema.PromptResponse(AcpSchema.StopReason.CANCELLED));
314		}
315	
316		/**
317		 * A prompt handler's answer, with stop reason {@code cancelled} once session/cancel was
318		 * received for the prompt: the agent must then answer cancelled (ACP v1, prompt turn,
319		 * Cancellation), also when its handler returned another stop reason. {@code _meta} is kept.
320		 */
321		private static Object cancelledIfCancelling(ActivePrompts.Turn turn, AcpSchema.JSONRPCRequest request,
322				Object result) {
323			if (turn.answer().isCancelling() && result instanceof AcpSchema.PromptResponse response
324					&& !AcpSchema.StopReason.CANCELLED.equals(response.stopReason())) {
325				logger.debug("Prompt {} answered {} after session/cancel; sending cancelled", request.id(),
326						response.stopReason());
327				return new AcpSchema.PromptResponse(AcpSchema.StopReason.CANCELLED, response.meta());
328			}
329			return result;
330		}
331	
332		/**
333		 * The answer to a prompt whose handler failed after session/cancel: stop reason
334		 * {@code cancelled}, whatever the failure (ACP v1, prompt turn, Cancellation: agents must
335		 * catch the errors aborted work raises and answer cancelled). The failure is logged here.
336		 */
337		private static AcpSchema.JSONRPCResponse cancelledPromptAfterFailure(AcpSchema.JSONRPCRequest request,
338				Throwable error) {
339			logger.debug("Prompt {} failed after session/cancel; answering cancelled", request.id(), error);
340			return cancelledPrompt(request);
341		}
342	
343		/**
344		 * Extracts the sessionId from request parameters, which arrive as a {@code Map} from
345		 * the JSON transports and as the typed record from in-process transports.
346		 */
347		private String extractSessionId(@Nullable Object params) {
348			// The typed records come from in-process callers, which no nullness checker may
349			// have seen; a null key would fail the activePrompts map.
350			if (params instanceof AcpSchema.PromptRequest promptRequest) {
351				return promptRequest.sessionId() != null ? promptRequest.sessionId() : "unknown";
352			}
353			if (params instanceof AcpSchema.CancelNotification cancelNotification) {
354				return cancelNotification.sessionId() != null ? cancelNotification.sessionId() : "unknown";
355			}
356			if (params instanceof AcpSchema.CloseSessionRequest closeSessionRequest) {
357				return closeSessionRequest.sessionId() != null ? closeSessionRequest.sessionId() : "unknown";
358			}
359			if (params instanceof Map<?, ?> map) {
360				Object sessionId = map.get("sessionId");
361				return sessionId != null ? sessionId.toString() : "unknown";
362			}
363			return "unknown";
364		}
365	
366		record MethodNotFoundError(String method, String message, @Nullable Object data) {
367		}
368	
369		private MethodNotFoundError getMethodNotFoundError(String method) {
370			return new MethodNotFoundError(method, "Method not found: " + method, null);
371		}
372	
373		/**
374		 * Handles an incoming JSON-RPC notification by routing it to the appropriate handler.
375		 * A session/cancel notification does not end the active prompt's turn: the cancelled
376		 * prompt's response does (see ActivePrompts#cancel). A $/cancel_request cancels the
377		 * request it names, which is then answered with -32800 unless it already answered; a
378		 * cancelled prompt's turn ends before that answer is published.
379		 * @param notification The incoming JSON-RPC notification
380		 * @return A Mono that completes when the notification is processed
381		 */
382		private Mono<Void> handleIncomingNotification(AcpSchema.JSONRPCNotification notification) {
383			return Mono.defer(() -> {
384				// $/cancel_request: answered by the session itself, never by a handler
385				if (AcpSchema.METHOD_CANCEL_REQUEST.equals(notification.method())) {
386					this.inbound.cancel(notification);
387					return Mono.empty();
388				}
389	
390				// session/cancel: the turn stays until the cancelled prompt answers
391				if (AcpSchema.METHOD_SESSION_CANCEL.equals(notification.method())) {
392					activePrompts.cancel(extractSessionId(notification.params()));
393				}
394	
395				return InboundMessages.deliver(logger, notification, this.notificationHandlers, NotificationHandler::handle);
396			});
397		}
398	
399		/**
400		 * Sends a JSON-RPC request to the client and expects a response of type T.
401		 * This is used for agent→client requests like fs/read_text_file, terminal/*, etc.
402		 * @param <T> the type of the expected response
403		 * @param method the name of the method to call on the client
404		 * @param requestParams the parameters to send with the request
405		 * @param typeRef the TypeReference describing the expected response type
406		 * @return a Mono that will emit the response when received; an error response fails
407		 * it with {@link AcpError}
408		 */
409		@Override
410		public <T> Mono<T> sendRequest(String method, Object requestParams, TypeRef<T> typeRef) {
411			return this.outbound.sendRequest(method, requestParams, typeRef);
412		}
413	
414		/**
415		 * Sends a JSON-RPC notification to the client.
416		 * This is used for agent→client notifications like session/update.
417		 * @param method the name of the notification method
418		 * @param params the notification parameters
419		 * @return a Mono that completes when the notification is sent
420		 */
421		@Override
422		public Mono<Void> sendNotification(String method, @Nullable Object params) {
423			return this.outbound.sendNotification(method, params);
424		}
