426		/**
427		 * Checks if there is an active prompt being processed.
428		 * @return true if a prompt is currently active
429		 */
430		public boolean hasActivePrompt() {
431			return !activePrompts.isEmpty();
432		}
433	
434		/**
435		 * Checks if there is an active prompt being processed for the specified logical
436		 * ACP session.
437		 * @param sessionId the logical ACP session ID
438		 * @return true if a prompt is currently active for the session
439		 */
440		public boolean hasActivePrompt(String sessionId) {
441			Assert.hasText(sessionId, "The sessionId can not be empty");
442			return activePrompts.isActive(sessionId);
443		}
444	
445		/**
446		 * Whether the prompt now running on {@code sessionId} has been answered, by its handler or by
447		 * the session when a prompt deadline passed, as the session sees it later: the SDK's prompt
448		 * contexts ask it before each update, since ACP requires a prompt's updates to precede its
449		 * answer. The answer is about the prompt running at this call; when none is, it is always
450		 * {@code false}.
451		 * @param sessionId the logical ACP session ID
452		 * @return a check, true once that prompt has been answered
453		 */
454		public BooleanSupplier promptAnswered(String sessionId) {
455			Assert.hasText(sessionId, "The sessionId can not be empty");
456			ActivePrompts.Turn turn = activePrompts.current(sessionId);
457			if (turn == null) {
458				return () -> false;
459			}
460			return turn::isAnswered;
461		}
462	
463		/**
464		 * Gets one active prompt session ID, if any.
465		 *
466		 * <p>
467		 * This is a legacy aggregate view. When multiple logical ACP sessions are active on
468		 * the same transport connection, the returned session ID is arbitrary.
469		 * </p>
470		 * @return one active session ID or null if no prompt is active
471		 */
472		public @Nullable String getActivePromptSessionId() {
473			return activePrompts.anySessionId();
474		}
475	
476		/**
477		 * Gets the logical ACP session IDs that currently have active prompts.
478		 * @return an immutable snapshot of active prompt session IDs
479		 */
480		public Set<String> getActivePromptSessionIds() {
481			return activePrompts.sessionIds();
482		}
483	
484		/**
485		 * Closes the session gracefully, allowing pending operations to complete.
486		 * @return A Mono that completes when the session is closed
487		 */
488		@Override
489		public Mono<Void> closeGracefully() {
490			return Mono.fromRunnable(() -> {
491				this.inbound.cancelAll();
492				activePrompts.clear();
493				dismissPendingResponses();
494			}).then(this.transport.closeGracefully());
495		}
496	
497		/**
498		 * Closes the session immediately, potentially interrupting pending operations.
499		 */
500		@Override
501		public void close() {
502			this.inbound.cancelAll();
503			activePrompts.clear();
504			dismissPendingResponses();
505			transport.close();
506		}
507	
508	}

