 27	/**
 28	 * Agent-side implementation of the ACP (Agent Client Protocol) session that manages
 29	 * bidirectional JSON-RPC communication between agents and clients. This is the agent-side
 30	 * counterpart to {@link AcpClientSession}.
 31	 *
 32	 * <p>
 33	 * The session manages:
 34	 * <ul>
 35	 * <li>Request/response handling with unique message IDs</li>
 36	 * <li>Notification processing</li>
 37	 * <li>Message timeout management</li>
 38	 * <li>Transport layer abstraction</li>
 39	 * <li>Single-turn enforcement (only one prompt active at a time per session; a turn ends
 40	 * with its prompt's response, also after {@code session/cancel})</li>
 41	 * </ul>
 42	 *
 43	 * <p>
 44	 * This is the agent-side session that receives requests from clients (initialize,
 45	 * newSession, prompt, etc.) and sends requests to clients (readTextFile, writeTextFile,
 46	 * requestPermission, etc.)
 47	 * </p>
 48	 *
 49	 * @author Mark Pollack
 50	 */
 51	public class AcpAgentSession implements AcpSession {
 52	
 53		private static final Logger logger = LoggerFactory.getLogger(AcpAgentSession.class);
 54	
 55		/** Transport layer implementation for message exchange */
 56		private final AcpAgentTransport transport;
 57	
 58		/** Requests and notifications sent to the client, and the requests waiting for a response */
 59		private final OutboundMessages outbound;
 60	
 61		/** Map of request handlers keyed by method name */
 62		private final ConcurrentHashMap<String, RequestHandler<?>> requestHandlers = new ConcurrentHashMap<>();
 63	
 64		/** Map of notification handlers keyed by method name */
 65		private final ConcurrentHashMap<String, NotificationHandler> notificationHandlers = new ConcurrentHashMap<>();
 66	
 67		/** Requests from the client still being handled, which a $/cancel_request can cancel */
 68		private final InboundRequests inbound = new InboundRequests();
 69	
 70		/** Single-turn enforcement: the active prompt of each logical ACP sessionId. */
 71		private final ActivePrompts activePrompts = new ActivePrompts();
 72	
 73		/** The cancel grace period and maximum prompt duration of each prompt. */
 74		private final PromptDeadlines promptDeadlines;
 75	
 76		/**
 77		 * Set when the transport's {@code start()} fails (already started, port in use, ...).
 78		 * Requests to the client are then failed immediately with the cause.
 79		 */
 80		private volatile @Nullable Throwable startFailure;
 81	
 82		/**
 83		 * Functional interface for handling incoming JSON-RPC requests. Implementations
 84		 * should process the request parameters and return a response.
 85		 *
 86		 * @param <T> Response type
 87		 */
 88		@FunctionalInterface
 89		public interface RequestHandler<T> {
 90	
 91			/**
 92			 * Handles an incoming request with the given parameters.
 93			 * @param params The request parameters; an omitted params arrives as an empty
 94			 * object
 95			 * @return A Mono containing the response object; it must not complete empty
 96			 */
 97			Mono<T> handle(Object params);
 98	
 99		}
100	
101		/**
102		 * Functional interface for handling incoming JSON-RPC notifications. Implementations
103		 * should process the notification parameters without returning a response.
104		 */
105		@FunctionalInterface
106		public interface NotificationHandler {
107	
108			/**
109			 * Handles an incoming notification with the given parameters.
110			 * @param params The notification parameters; an omitted params arrives as an empty
111			 * object
112			 * @return A Mono that completes when the notification is processed
113			 */
114			Mono<Void> handle(Object params);
115	
116		}
