  5	package com.agentclientprotocol.sdk.error;
  6	
  7	import java.util.Map;
  8	
  9	/**
 10	 * The JSON-RPC error codes ACP defines, as constants: use them to answer a request with an error by
 11	 * throwing an {@link AcpProtocolException} from a handler, and to compare with
 12	 * {@link com.agentclientprotocol.sdk.spec.AcpError#getCode()} when a request you sent failed.
 13	 * {@link #getDescription(int)} gives a code's short name for messages and logs.
 14	 *
 15	 * <p>Every constant is a code from the ACP v1 schema ({@code $defs.ErrorCode}): the JSON-RPC 2.0
 16	 * standard codes, {@code -32800} (request cancelled), and the two codes ACP defines in its reserved
 17	 * range {@code -32000..-32099}: {@code -32000} (authentication required) and {@code -32002}
 18	 * (resource not found). The SDK uses no other code in the reserved range, because a peer reads any
 19	 * code there as the meaning ACP gives it, or will give it. Each constant says when the SDK answers
 20	 * with it by itself; the last two it never sends on its own, they are for handlers.
 21	 *
 22	 * @author Mark Pollack
 23	 * @see <a href="https://www.jsonrpc.org/specification#error_object">JSON-RPC Error Object</a>
 24	 */
 25	public final class AcpErrorCodes {
 26	
 27		private AcpErrorCodes() {
 28			// Utility class - no instantiation
 29		}
 30	
 31		// --------------------------
 32		// Standard JSON-RPC Errors
 33		// --------------------------
 34	
 35		/**
 36		 * Parse error ({@code -32700}): the message was not valid JSON. The SDK's transports answer a
 37		 * message they cannot parse with it, with a {@code null} id, and keep reading.
 38		 */
 39		public static final int PARSE_ERROR = -32700;
 40	
 41		/**
 42		 * Invalid request ({@code -32600}): the message is JSON but not a valid JSON-RPC request, or
 43		 * the request is not valid in the current state. The SDK answers with it a JSON message it
 44		 * cannot read as a JSON-RPC message, and a second {@code session/prompt} on a session whose
 45		 * prompt turn is still running, with data {@code {"sessionId": ...}}.
 46		 */
 47		public static final int INVALID_REQUEST = -32600;
 48	
 49		/**
 50		 * Method not found ({@code -32601}): the peer has no handler for the method. Both sides answer
 51		 * with it a request for which no handler is registered, extension methods included.
 52		 */
 53		public static final int METHOD_NOT_FOUND = -32601;
 54	
 55		/**
 56		 * Invalid params ({@code -32602}): the params do not fit the method. Both sides answer with it
 57		 * a request whose params cannot be read as the handler's params type, or lack a field the ACP
 58		 * schema requires; handlers use it for params they read but do not accept.
 59		 */
 60		public static final int INVALID_PARAMS = -32602;
 61	
 62		/**
 63		 * Internal error ({@code -32603}): the handler failed. Both sides answer with it a request
 64		 * whose handler threw an exception other than {@link AcpProtocolException}, or produced no
 65		 * response. It is also the code of the {@link com.agentclientprotocol.sdk.spec.AcpError} that
 66		 * fails a request whose response the SDK rejected.
 67		 */
 68		public static final int INTERNAL_ERROR = -32603;
 69	
 70		/**
 71		 * Request cancelled ({@code -32800}): the method's work was stopped, because the caller
 72		 * cancelled the request ({@code $/cancel_request}) or because of resource constraints or
 73		 * shutdown. ACP answers an internally cancelled request (an internal timeout, for one) with
 74		 * this code too. The SDK answers with it a request whose handler it cancelled for a
 75		 * {@code $/cancel_request}, a handler that failed with a
 76		 * {@link java.util.concurrent.CancellationException} or an interrupt, and a prompt that ran
 77		 * past the agent's maximum prompt duration.
 78		 */
 79		public static final int REQUEST_CANCELLED = -32800;
 80	
 81		// --------------------------
 82		// ACP-Specific Errors
 83		// --------------------------
 84	
 85		/**
 86		 * Authentication required ({@code -32000}): the agent requires {@code authenticate} before this
 87		 * request. An agent's handler answers with it; the SDK never does by itself.
 88		 */
 89		public static final int AUTHENTICATION_REQUIRED = -32000;
 90	
 91		/**
 92		 * Resource not found ({@code -32002}): a resource the request names, such as a file or a
 93		 * session, does not exist. A handler answers with it; the SDK never does by itself.
 94		 */
 95		public static final int RESOURCE_NOT_FOUND = -32002;
 96	
 97		private static final Map<Integer, String> DESCRIPTIONS = Map.ofEntries(Map.entry(PARSE_ERROR, "Parse error"),
 98				Map.entry(INVALID_REQUEST, "Invalid request"), Map.entry(METHOD_NOT_FOUND, "Method not found"),
 99				Map.entry(INVALID_PARAMS, "Invalid params"), Map.entry(INTERNAL_ERROR, "Internal error"),
100				Map.entry(REQUEST_CANCELLED, "Request cancelled"),
101				Map.entry(AUTHENTICATION_REQUIRED, "Authentication required"),
102				Map.entry(RESOURCE_NOT_FOUND, "Resource not found"));
103	
104	
105		/**
106		 * Returns the short name of an error code as JSON-RPC and ACP spell it, such as
107		 * {@code "Method not found"} for {@code -32601}.
108		 * @param code the error code
109		 * @return the code's name, or {@code "Unknown error"} for a code not defined here
110		 */
111		public static String getDescription(int code) {
112			return DESCRIPTIONS.getOrDefault(code, "Unknown error");
113		}
114	
115	}
