313	/**
314	 * The exception a request handler throws to answer the request with a JSON-RPC error: the peer
315	 * receives its code, message and data as the error response. Throw it, or fail the handler's
316	 * {@code Mono} with it, for a failure the caller should see, with a code from
317	 * {@link AcpErrorCodes}; this works the same in agent and client handlers, builder lambdas and
318	 * annotated methods. Its message and data go to the peer as they are, so keep secrets out of them.
319	 * An {@code AcpError} that escapes a handler passes on the error it carries, and a
320	 * {@link java.util.concurrent.CancellationException} is answered {@code -32800} (request
321	 * cancelled) with its own message, as ACP asks for a request cancelled internally. Any other
322	 * exception from a handler is answered {@code -32603} (internal error) with the generic message
323	 * "Internal error"; that exception is logged on the handling side and not sent.
324	 *
325	 * <p>The caller of the request never receives this type. On the caller's side the error response
326	 * fails the request with {@link com.agentclientprotocol.sdk.spec.AcpError}, which carries the same
327	 * code, message and data. A handler that calls the peer and lets an {@code AcpError} it received
328	 * escape passes that error on unchanged; it need not convert it.
329	 *
330	 * <p>Codes a handler commonly answers with:
331	 * <ul>
332	 * <li>{@link AcpErrorCodes#INVALID_PARAMS} ({@code -32602}): the params are readable but not
333	 * acceptable, such as an unknown config option value</li>
334	 * <li>{@link AcpErrorCodes#RESOURCE_NOT_FOUND} ({@code -32002}): a session, file or other resource
335	 * the request names does not exist</li>
336	 * <li>{@link AcpErrorCodes#AUTHENTICATION_REQUIRED} ({@code -32000}): the client must call
337	 * {@code authenticate} first</li>
338	 * <li>{@link AcpErrorCodes#INVALID_REQUEST} ({@code -32600}): the request is not valid in the
339	 * current state</li>
340	 * <li>{@link AcpErrorCodes#REQUEST_CANCELLED} ({@code -32800}): the handler stopped because its
341	 * work was cancelled</li>
342	 * </ul>
343	 *
344	 * <p>Thrown from a notification handler, it is logged and dropped: a notification gets no answer.
345	 * {@link #getMessage()} puts the code in front of the message, for logs; {@link #getErrorMessage()}
346	 * is the message the peer receives.
347	 *
348	 * <p>Example, in a handler that looks a session up:
349	 * <pre>{@code
350	 * if (!sessions.containsKey(request.sessionId())) {
351	 *     throw new AcpProtocolException(AcpErrorCodes.RESOURCE_NOT_FOUND,
352	 *             "Unknown session: " + request.sessionId());
353	 * }
354	 * }</pre>
355	 *
356	 * @author Mark Pollack
357	 * @see AcpErrorCodes
358	 * @see com.agentclientprotocol.sdk.spec.AcpError
359	 */
360	public class AcpProtocolException extends AcpException {
361	
362		/** The JSON-RPC error code. */
363		private final int code;
364	
365		/** The error data, or null for none. */
366		private final @Nullable Object data;
367	
368		/** The error message without the code. */
369		private final String errorMessage;
370	
371		/**
372		 * Creates the exception for an error response with this code and message and no data.
373		 * @param code the JSON-RPC error code, usually one of {@link AcpErrorCodes}
374		 * @param message the error message the peer receives
375		 */
376		public AcpProtocolException(int code, String message) {
377			this(code, message, null);
378		}
379	
380		/**
381		 * Creates the exception for an error response with this code, message and data.
382		 * @param code the JSON-RPC error code, usually one of {@link AcpErrorCodes}
383		 * @param message the error message the peer receives
384		 * @param data more detail for the peer, any value the JSON mapper can write, or {@code null}
385		 * for none
386		 */
387		public AcpProtocolException(int code, String message, @Nullable Object data) {
388			super(formatMessage(code, message));
389			this.code = code;
390			this.data = data;
391			this.errorMessage = message;
392		}
393	
394		/**
395		 * Returns the JSON-RPC error code the peer receives.
396		 * @return the error code
397		 * @see AcpErrorCodes
398		 */
399		public int getCode() {
400			return code;
401		}
402	
403		/**
404		 * Returns the data the peer receives with the error.
405		 * @return the data, or {@code null} if there is none
406		 */
407		public @Nullable Object getData() {
408			return data;
409		}
410	
411		/**
412		 * Returns the error message the peer receives, without the code. {@link #getMessage()} puts the
413		 * code in front of it, as {@code [-32602] message}, for logs.
414		 * @return the error message
415		 */
416		public String getErrorMessage() {
417			return errorMessage;
418		}
419	
420		/**
421		 * Returns whether the code is {@code -32601} ("Method not found").
422		 * @return true for {@link AcpErrorCodes#METHOD_NOT_FOUND}
423		 */
424		public boolean isMethodNotFound() {
425			return code == AcpErrorCodes.METHOD_NOT_FOUND;
426		}
427	
428		/**
429		 * Returns whether the code is {@code -32000} (authentication required).
430		 * @return true for {@link AcpErrorCodes#AUTHENTICATION_REQUIRED}
431		 */
432		public boolean isAuthenticationRequired() {
433			return code == AcpErrorCodes.AUTHENTICATION_REQUIRED;
434		}
435	
436		/**
437		 * Returns whether the code is {@code -32602} ("Invalid params").
438		 * @return true for {@link AcpErrorCodes#INVALID_PARAMS}
439		 */
440		public boolean isInvalidParams() {
441			return code == AcpErrorCodes.INVALID_PARAMS;
442		}
443	
444		/**
445		 * Returns whether the code is {@code -32603} ("Internal error").
446		 * @return true for {@link AcpErrorCodes#INTERNAL_ERROR}
447		 */
448		public boolean isInternalError() {
449			return code == AcpErrorCodes.INTERNAL_ERROR;
450		}
451	
452		private static String formatMessage(int code, String message) {
453			return "[" + code + "] " + message;
454		}
455	
456	}
