531	
532	import java.lang.reflect.InvocationTargetException;
533	import java.lang.reflect.RecordComponent;
534	import java.util.Collection;
535	
536	import com.fasterxml.jackson.annotation.JsonProperty;
537	import org.jspecify.annotations.Nullable;
538	
539	/**
540	 * Finds a required field missing from inbound params or from a response's result. A schema
541	 * record's component without {@code @Nullable} is one the ACP schema lists as
542	 * {@code required}; Jackson reads an absent one as null, which a handler or caller would only
543	 * find when it fails on it. Only the schema's records
544	 * ({@link AcpSchema}) are checked: an application's own record, such as an extension method's
545	 * params, has no schema behind it, and its nullness is its own business.
546	 */
547	final class RequiredFields {
548	
549		private RequiredFields() {
550		}
551	
552		/**
553		 * The JSON path of the first required field that is null, looking into nested records
554		 * and collections of records; null when none is.
555		 */
556		static @Nullable String firstMissing(@Nullable Object value) {
557			return firstMissing(value, "");
558		}
559	
560		private static @Nullable String firstMissing(@Nullable Object value, String path) {
561			if (value instanceof Collection<?> collection) {
562				return firstMissingInElements(collection, path);
563			}
564			if (value == null || !isSchemaRecord(value.getClass())) {
565				return null;
566			}
567			for (RecordComponent component : value.getClass().getRecordComponents()) {
568				String missing = firstMissingInComponent(component, value, path);
569				if (missing != null) {
570					return missing;
571				}
572			}
573			return null;
574		}
575	
576		private static boolean isSchemaRecord(Class<?> type) {
577			return type.isRecord() && type.getName().startsWith(AcpSchema.class.getName() + "$");
578		}
579	
580		private static @Nullable String firstMissingInElements(Collection<?> collection, String path) {
581			int index = 0;
582			for (Object element : collection) {
583				String missing = firstMissing(element, path + "[" + index++ + "]");
584				if (missing != null) {
585					return missing;
586				}
587			}
588			return null;
589		}
590	
591		private static @Nullable String firstMissingInComponent(RecordComponent component, Object record, String path) {
592			String name = path.isEmpty() ? jsonName(component) : path + "." + jsonName(component);
593			Object field = read(component, record);
594			if (field != null) {
595				return firstMissing(field, name);
596			}
597			boolean optional = component.getAnnotatedType().isAnnotationPresent(Nullable.class)
598					|| component.getType().isPrimitive();
599			return optional ? null : name;
600		}
601	
602		private static String jsonName(RecordComponent component) {
603			JsonProperty property = component.getAnnotation(JsonProperty.class);
604			return (property != null && !property.value().isEmpty()) ? property.value() : component.getName();
605		}
606	
607		private static @Nullable Object read(RecordComponent component, Object record) {
608			try {
609				return component.getAccessor().invoke(record);
610			}
611			catch (IllegalAccessException | InvocationTargetException e) {
612				// A record nested in a type this package cannot reach: no check rather than a failure.
613				return null;
614			}
615		}
616	
617	}
