122	import java.util.Collections;
123	import java.util.LinkedHashMap;
124	import java.util.Map;
125	
126	import com.agentclientprotocol.sdk.error.AcpErrorCodes;
127	import com.agentclientprotocol.sdk.error.AcpException;
128	import org.jspecify.annotations.Nullable;
129	
130	/**
131	 * The failure a caller catches when a request it sent did not succeed: the peer answered with a
132	 * JSON-RPC error, or answered with a result the SDK rejected. It fails the request's {@code Mono}
133	 * on the asynchronous API and is thrown as it is by the sync API, on the client side and the agent
134	 * side alike, so one {@code catch (AcpError e)} covers both cases. Branch on {@link #getCode()}
135	 * (see {@link AcpErrorCodes}). To answer a request with an error from a handler, throw
136	 * {@link com.agentclientprotocol.sdk.error.AcpProtocolException} instead.
137	 *
138	 * <p>The two cases, which the data tells apart:
139	 * <ul>
140	 * <li>The peer answered with an error. {@link #getCode()}, the message and {@link #getData()} are
141	 * the peer's. A Java peer answers {@code -32601} ("Method not found") when it has no handler for
142	 * the method, {@code -32602} ("Invalid params") when it cannot read the params, {@code -32800} when
143	 * the request was cancelled, and {@code -32603} when its handler failed; a handler can answer any
144	 * code it chooses.</li>
145	 * <li>The peer answered with a success response the SDK rejected: the result lacks a field the ACP
146	 * schema requires, there is no result, or it cannot be read as the method's result type. The code
147	 * is {@code -32603} (internal error; JSON-RPC 2.0 defines none for an invalid response), the
148	 * message names the method and the problem, and {@link #getData()} is a map whose {@code "reason"}
149	 * is {@code "missing-required-field"} (with the field's path under {@code "field"}),
150	 * {@code "missing-result"} or {@code "unreadable-result"}, and whose {@code "method"} names the
151	 * request's method. A prompt context's {@code askChoice} answered with an option it did not offer
152	 * fails the same way, with reason {@code "unoffered-option"} and the {@code "optionId"}. Nothing is
153	 * sent back to the peer.</li>
154	 * </ul>
155	 *
156	 * <p>Other failures of a request have their own types:
157	 * {@link com.agentclientprotocol.sdk.error.AcpCapabilityException AcpCapabilityException} for a
158	 * call the peer did not advertise, refused before sending;
159	 * {@link com.agentclientprotocol.sdk.error.AcpConnectionException AcpConnectionException} for a
160	 * request the connection could not carry: one waiting when the connection ended, or sent after it
161	 * ended or the transport closed; and a
162	 * {@link java.util.concurrent.TimeoutException} for a request that got no answer in time, which the
163	 * sync API throws as
164	 * {@link com.agentclientprotocol.sdk.error.AcpTimeoutException AcpTimeoutException}. All of these,
165	 * and this class, extend {@link AcpException}, so {@code catch (AcpException e)} covers every way
166	 * a request can fail in the SDK; catch this class to handle the peer's answer alone.
167	 *
168	 * <p>A handler that lets an {@code AcpError} escape answers its own request with the error this
169	 * exception carries, unchanged: the peer's code, message and data, or for a rejected response the
170	 * SDK's {@code -32603} and data. So a handler that calls the other side and has nothing to add
171	 * just lets the failure propagate. To answer with a different error, catch it and throw an
172	 * {@link com.agentclientprotocol.sdk.error.AcpProtocolException} instead.
173	 *
174	 * <p>{@link #getMessage()} is the peer's message, followed by the detail its data carries, if any;
175	 * for a rejected response it is the SDK's message alone. It leaves out the code, which
176	 * {@link #getCode()} returns, so {@code e.getCode() + " " + e.getMessage()} names it once;
177	 * {@link #toString()}, which stack traces show, includes it.
178	 *
179	 * <p>Example, a client that falls back when the agent does not know an extension method:
180	 * <pre>{@code
181	 * Object buffers;
182	 * try {
183	 *     buffers = client.sendExtRequest("_example.com/workspace/buffers", Map.of());
184	 * }
185	 * catch (AcpError e) {
186	 *     if (e.getCode() != AcpErrorCodes.METHOD_NOT_FOUND) {
187	 *         throw e;
188	 *     }
189	 *     buffers = Map.of();
190	 * }
191	 * }</pre>
192	 */
193	public class AcpError extends AcpException {
194	
195		/** The error the peer sent, or the SDK built for a rejected response. */
196		private final AcpSchema.JSONRPCError error;
197	
198		/**
199		 * Creates the failure for an error response from the peer. The SDK creates it when a request is
200		 * answered with an error; an application needs it only to fake a failed request, in a test for
201		 * example.
202		 * @param error the error as the peer sent it
203		 */
204		public AcpError(AcpSchema.JSONRPCError error) {
205			super(buildErrorMessage(error, false));
206			this.error = error;
207		}
208	
209		private AcpError(AcpSchema.JSONRPCError error, String message) {
210			super(message);
211			this.error = error;
212		}
213	
214		/**
215		 * Returns the failure for a success response the SDK rejected: code {@code -32603}, the given
216		 * message as it is, and data naming the reason and the method, followed by the detail (see the
217		 * class description). The SDK calls it from more than one of its packages, which is why it is
218		 * public.
219		 * @param method the method of the request whose response was rejected
220		 * @param reason why, for example {@code "missing-required-field"}
221		 * @param message the message, naming the method and the problem
222		 * @param detail more data entries, for example the missing field's path; empty for none
223		 * @return the failure
224		 */
225		public static AcpError rejectedResponse(String method, String reason, String message, Map<String, Object> detail) {
226			Map<String, Object> data = new LinkedHashMap<>();
227			data.put("reason", reason);
228			data.put("method", method);
229			data.putAll(detail);
230			return new AcpError(new AcpSchema.JSONRPCError(AcpErrorCodes.INTERNAL_ERROR, message,
231					Collections.unmodifiableMap(data)), message);
232		}
233	
234		/**
235		 * Returns the class name, the message, the code and the data's detail, as stack traces show
236		 * them, for example
237		 * {@code com.agentclientprotocol.sdk.spec.AcpError: No such session [code=-32002]}. Unlike
238		 * {@link #getMessage()}, it includes the code.
239		 * @return the description
240		 */
241		// getMessage() leaves the code out on purpose (getCode() returns it); a stack trace and a
242		// log of the exception itself still name it.
243		@SuppressWarnings("OverrideThrowableToString")
244		@Override
245		public String toString() {
246			return getClass().getName() + ": " + buildErrorMessage(this.error, true);
247		}
248	
249		private static String buildErrorMessage(AcpSchema.JSONRPCError error, boolean withCode) {
250			StringBuilder sb = new StringBuilder();
251			sb.append(error.message());
252			if (withCode) {
253				sb.append(" [code=").append(error.code()).append("]");
254			}
255			if (error.data() != null) {
256				sb.append(": ").append(formatErrorData(error.data()));
257			}
258			return sb.toString();
259		}
260	
261		private static String formatErrorData(Object data) {
262			if (data instanceof java.util.Map<?, ?> map) {
263				// Extract common fields for better readability
264				Object details = map.get("details");
265				if (details != null) {
266					return details.toString();
267				}
268				Object reason = map.get("reason");
269				if (reason != null) {
270					return reason.toString();
271				}
272			}
273			return data.toString();
274		}
275	
276		/**
277		 * Returns the JSON-RPC error itself: its code, message and data, as the peer sent them or as
278		 * the SDK built them for a rejected response.
279		 * @return the error
280		 */
281		public AcpSchema.JSONRPCError getError() {
282			return error;
283		}
284	
285		/**
286		 * Returns the error code, such as {@link AcpErrorCodes#METHOD_NOT_FOUND}.
287		 * @return the code
288		 */
289		public int getCode() {
290			return error.code();
291		}
292	
293		/**
294		 * Returns the error's data: the detail the peer added, any JSON value (a {@code Map} for an
295		 * object), or for a rejected response the map the class description lists.
296		 * @return the data, or {@code null} if there is none
297		 */
298		public @Nullable Object getData() {
299			return error.data();
300		}
301	
302	}
