539	/**
540	 * Finds a required field missing from inbound params or from a response's result. A schema
541	 * record's component without {@code @Nullable} is one the ACP schema lists as
542	 * {@code required}; Jackson reads an absent one as null, which a handler or caller would only
543	 * find when it fails on it. Only the schema's records
544	 * ({@link AcpSchema}) are checked: an application's own record, such as an extension method's
545	 * params, has no schema behind it, and its nullness is its own business.
546	 */
547	final class RequiredFields {
548	
549		private RequiredFields() {
550		}
551	
552		/**
553		 * The JSON path of the first required field that is null, looking into nested records
554		 * and collections of records; null when none is.
555		 */
556		static @Nullable String firstMissing(@Nullable Object value) {
557			return firstMissing(value, "");
558		}
559	
560		private static @Nullable String firstMissing(@Nullable Object value, String path) {
561			if (value instanceof Collection<?> collection) {
562				return firstMissingInElements(collection, path);
563			}
564			if (value == null || !isSchemaRecord(value.getClass())) {
565				return null;
566			}
567			for (RecordComponent component : value.getClass().getRecordComponents()) {
568				String missing = firstMissingInComponent(component, value, path);
569				if (missing != null) {
570					return missing;
571				}
572			}
573			return null;
