670				}
671				sink.next(value);
672			}
673			else if (AcpSchema.DefaultOnNull.class.isAssignableFrom(rawClass(typeRef.getType()))) {
674				sink.next(transport.unmarshalFrom(Map.of(), typeRef));
675			}
676			else if (ExtensionMethods.isExtension(method)) {
677				sink.complete();
678			}
679			else {
