560: 		return afterInitialize(AcpSchema.METHOD_SESSION_PROMPT, AcpAsyncClient::initializedOnly, () -> {
561: 			if (session instanceof AcpClientSession clientSession) {
562: 				return clientSession.sendRequest(AcpSchema.METHOD_SESSION_PROMPT, request,
563: 						PROMPT_RESPONSE_TYPE_REF, this.promptTimeout);
564: 			}
565: 			return session.sendRequest(AcpSchema.METHOD_SESSION_PROMPT, request, PROMPT_RESPONSE_TYPE_REF);
566: 		});
567: 	}
589: 	public Mono<AcpSchema.PromptResponse> prompt(AcpSchema.PromptRequest request, CancellationSignal stop) {
590: 		Assert.notNull(request, "Prompt request must not be null");
591: 		Assert.notNull(stop, "Cancellation signal must not be null");
592: 		return Mono.create(sink -> {
593: 			// The prompt is subscribed first, so its request is handed to the transport before
594: 			// a session/cancel the signal triggers.
595: 			Disposable prompt = prompt(request).contextWrite(sink.contextView())
596: 				.subscribe(sink::success, sink::error, () -> sink.success());
597: 			Disposable cancel = stop.whenCancelled()
598: 				.then(Mono.defer(() -> cancel(new AcpSchema.CancelNotification(request.sessionId()))))
599: 				.subscribe(v -> {
600: 				}, error -> logger.debug("No session/cancel sent for session {}: {}", request.sessionId(),
601: 						error.getMessage()));
