603: 				cancel.dispose();
604: 				prompt.dispose();
605: 			});
606: 		});
607: 	}
621: 	public Mono<Void> cancel(AcpSchema.CancelNotification notification) {
622: 		Assert.notNull(notification, "Cancel notification must not be null");
623: 		logger.debug("Canceling operations for session: {}", notification.sessionId());
624: 		return afterInitialize(AcpSchema.METHOD_SESSION_CANCEL, AcpAsyncClient::initializedOnly,
625: 				() -> session.sendNotification(AcpSchema.METHOD_SESSION_CANCEL, notification));
626: 	}
628: 	// --------------------------
629: 	// Extension Methods
630: 	// --------------------------
647: 	public <T> Mono<T> sendExtRequest(String method, Object params, TypeRef<T> resultType) {
648: 		ExtensionMethods.requireExtension(method);
649: 		Assert.notNull(params, "Params must not be null");
650: 		Assert.notNull(resultType, "Result type must not be null");
651: 		// Extension methods are outside ACP's lifecycle: the peer decides whether it needs
652: 		// initialize first.
653: 		return session.sendRequest(method, params, resultType);
654: 	}
666: 	public Mono<Object> sendExtRequest(String method, Object params) {
667: 		return sendExtRequest(method, params, RAW_RESULT_TYPE_REF);
668: 	}
678: 	public Mono<Void> sendExtNotification(String method, Object params) {
679: 		ExtensionMethods.requireExtension(method);
680: 		Assert.notNull(params, "Params must not be null");
681: 		// Extension methods are outside ACP's lifecycle: the peer decides whether it needs
682: 		// initialize first.
683: 		return session.sendNotification(method, params);
684: 	}
686: 	// --------------------------
687: 	// Order and capabilities
688: 	// --------------------------
695: 	private static Consumer<NegotiatedCapabilities> withDirectories(Consumer<NegotiatedCapabilities> requirement,
696: 			@Nullable List<String> additionalDirectories) {
697: 		if (additionalDirectories == null || additionalDirectories.isEmpty()) {
698: 			return requirement;
699: 		}
700: 		return requirement.andThen(NegotiatedCapabilities::requireAdditionalDirectories);
701: 	}
704: 	private static void initializedOnly(NegotiatedCapabilities capabilities) {
705: 		// any agent serves the call
706: 	}
715: 	private <T> Mono<T> afterInitialize(String method, Consumer<NegotiatedCapabilities> requirement,
716: 			Supplier<Mono<T>> send) {
717: 		return Mono.defer(() -> {
718: 			NegotiatedCapabilities capabilities = this.agentCapabilities.get();
719: 			if (capabilities == null) {
720: 				return Mono.error(new IllegalStateException("Call initialize() first: the agent has not answered "
721: 						+ "initialize, so the client does not send " + method));
722: 			}
723: 			requirement.accept(capabilities);
724: 			return send.get();
725: 		});
726: 	}
728: 	// --------------------------
729: 	// Lifecycle Management
730: 	// --------------------------
739: 	public void close() {
740: 		logger.debug("Closing ACP client");
741: 		session.close();
742: 		transport.close();
743: 	}
754: 	public Mono<Void> closeGracefully() {
755: 		logger.debug("Gracefully closing ACP client");
756: 		return session.closeGracefully().then(transport.closeGracefully());
757: 	}
759: }

