309: 		Assert.notNull(handler, "The handler can not be null");
310: 		this.exceptionHandler = handler;
311: 	}
321: 	public void awaitProcessExit() {
322: 		Process process = this.process;
323: 		if (process == null) {
324: 			throw new IllegalStateException("The agent process has not been started: connect first");
325: 		}
326: 		try {
327: 			process.waitFor();
328: 		}
329: 		catch (InterruptedException e) {
330: 			Thread.currentThread().interrupt();
331: 			CancellationException cancelled = new CancellationException(
332: 					"Interrupted while waiting for the agent process to exit");
333: 			cancelled.initCause(e);
334: 			throw cancelled;
335: 		}
336: 	}
342: 	private void startErrorProcessing(Process process) {
343: 		readLines(this.errorScheduler, process.getErrorStream(), "error stream", this::emitError,
344: 				failure -> this.errorSink.tryEmitComplete());
345: 	}
347: 	private boolean emitError(String line) {
348: 		try {
349: 			if (this.errorSink.tryEmitNext(line).isSuccess()) {
350: 				return true;
351: 			}
352: 			if (!isClosing) {
353: 				logger.error("Failed to emit error message");
354: 			}
355: 		}
356: 		catch (Exception e) {
357: 			if (!isClosing) {
358: 				logger.error("Error processing error message", e);
359: 			}
360: 		}
361: 		return false;
362: 	}
371: 	private void readLines(Scheduler scheduler, InputStream stream, String streamName, Predicate<String> accept,
372: 			Consumer<@Nullable Throwable> onEnd) {
373: 		scheduler.schedule(() -> {
374: 			Throwable failure = null;
375: 			try (BufferedReader reader = new BufferedReader(new InputStreamReader(stream, StandardCharsets.UTF_8))) {
376: 				while (!isClosing) {
377: 					String line = reader.readLine();
378: 					if (line == null || !accept.test(line)) {
379: 						break;
380: 					}
381: 				}
382: 			}
383: 			catch (IOException e) {
384: 				if (!isClosing) {
385: 					failure = e;
386: 					logger.error("Error reading from " + streamName, e);
387: 					this.exceptionHandler.accept(e);
388: 				}
389: 			}
390: 			catch (RuntimeException | Error e) {
391: 				// Not the stream: handling a line failed. Report the real cause, which would
392: 				// otherwise end the reading as if the agent had closed its output.
393: 				failure = e;
394: 				logger.error("Reading the agent's " + streamName + " failed", e);
395: 				this.exceptionHandler.accept(e);
396: 			}
397: 			finally {
398: 				isClosing = true;
399: 				onEnd.accept(failure);
400: 			}
401: 		});
402: 	}
404: 	private void handleIncomingMessages(Function<Mono<JSONRPCMessage>, Mono<JSONRPCMessage>> inboundMessageHandler) {
405: 		this.inboundSink.asFlux()
406: 			.flatMap(message -> Mono.just(message)
407: 				.transform(inboundMessageHandler)
408: 				.contextWrite(ctx -> ctx.put("observation", "myObservation")))
409: 			.subscribe(ignored -> {
410: 			}, error -> logger.warn("Inbound message processing ended with an error", error));
411: 	}
413: 	private void handleIncomingErrors() {
414: 		this.errorSink.asFlux()
415: 			.subscribe(line -> this.stdErrorHandler.accept(line),
416: 					error -> logger.warn("Stopped handing the agent's standard error to its handler", error));
417: 	}
426: 	@Override
427: 	public Mono<Void> sendMessage(JSONRPCMessage message) {
428: 		try {
429: 			OutboundSinks.emit(this.outboundSink, message);
430: 		}
431: 		catch (Sinks.EmissionException e) {
432: 			return Mono.error(OutboundSinks.isClosed(e) ? new AcpConnectionException("The transport is closed", e)
433: 					: new AcpConnectionException("The message could not be queued: " + e.getReason(), e));
434: 		}
435: 		return Mono.empty();
436: 	}
442: 	private void startInboundProcessing(Process process) {
443: 		readLines(this.inboundScheduler, process.getInputStream(), "input stream", this::emitInbound, failure -> {
444: 			this.inboundSink.tryEmitComplete();
445: 			terminated(process, failure);
446: 		});
447: 	}
454: 	private void terminated(Process process, @Nullable Throwable readFailure) {
455: 		if (this.closedLocally) {
456: 			this.terminationSink.tryEmitEmpty();
457: 			return;
458: 		}
459: 		if (readFailure != null) {
460: 			this.terminationSink.tryEmitError(
461: 					new AcpConnectionException("Reading the agent's output failed: " + readFailure, readFailure));
462: 			return;
463: 		}
464: 		String reason;
465: 		try {
466: 			// The agent normally exits right after its output ends; one that closed its
467: 			// output but goes on running can deliver nothing more either.
468: 			reason = process.waitFor(EXIT_WAIT.toMillis(), java.util.concurrent.TimeUnit.MILLISECONDS)
469: 					? exitDescription(process.exitValue())
470: 					: "ACP agent process closed its standard output but has not exited";
471: 		}
472: 		catch (InterruptedException e) {
473: 			Thread.currentThread().interrupt();
474: 			reason = "ACP agent process closed its standard output";
475: 		}
476: 		if (this.closedLocally) {
477: 			this.terminationSink.tryEmitEmpty();
478: 			return;
479: 		}
480: 		logger.info("{}", reason);
481: 		this.terminationSink.tryEmitError(new AcpConnectionException(reason));
482: 	}
488: 	static String exitDescription(int exitCode) {
489: 		String description = "ACP agent process exited with code " + exitCode;
490: 		boolean windows = System.getProperty("os.name", "").startsWith("Windows");
491: 		if (!windows && exitCode > 128 && exitCode < 128 + 65) {
492: 			description += " (signal " + (exitCode - 128) + ")";
493: 		}
494: 		return description;
495: 	}
502: 	private boolean emitInbound(String line) {
503: 		if (line.isBlank()) {
504: 			return true;
505: 		}
506: 		logger.trace("RECV: {}", line);
507: 		JSONRPCMessage message;
508: 		try {
509: 			message = AcpSchema.deserializeJsonRpcMessage(this.jsonMapper, line);
510: 		}
511: 		catch (Exception e) {
512: 			rejectUnreadable(line, e);
513: 			return true;
514: 		}
515: 		if (this.inboundSink.tryEmitNext(message).isSuccess()) {
516: 			return true;
517: 		}
518: 		if (!isClosing) {
519: 			logger.error("Failed to enqueue an inbound {}", message.getClass().getSimpleName());
520: 			logger.debug("Inbound message not enqueued: {}", message);
521: 		}
522: 		return false;
523: 	}
530: 	private void rejectUnreadable(String line, Exception e) {
531: 		if (!isClosing) {
532: 			logger.error("Skipped an inbound line that is not a JSON-RPC message", e);
533: 			logger.debug("Skipped inbound line: {}", line);
534: 		}
535: 		this.exceptionHandler.accept(e);
536: 		try {
537: 			OutboundSinks.emit(this.outboundSink, AcpSchema.unreadableMessageResponse(this.jsonMapper, line));
538: 		}
539: 		catch (Sinks.EmissionException emission) {
540: 			if (!isClosing) {
541: 				logger.error("Failed to answer an unreadable inbound line", emission);
542: 			}
543: 		}
544: 	}
551: 	private void startOutboundProcessing(Process process) {
552: 		this.handleOutbound(messages -> messages
553: 			// this bit is important since writes come from user threads, and we
554: 			// want to ensure that the actual writing happens on a dedicated thread
555: 			.publishOn(outboundScheduler)
556: 			.handle((message, sink) -> write(process, message, sink)));
557: 	}
563: 	private void write(Process process, JSONRPCMessage message, SynchronousSink<JSONRPCMessage> sink) {
564: 		if (isClosing) {
565: 			return;
566: 		}
567: 		try {
568: 			// Messages are delimited by newlines, and MUST NOT contain embedded newlines.
569: 			String jsonMessage = jsonMapper.writeValueAsString(message)
570: 				.replace("\r\n", "\\n")
571: 				.replace("\n", "\\n")
572: 				.replace("\r", "\\n");
573: 			logger.trace("SEND: {}", jsonMessage);
574: 			var os = process.getOutputStream();
575: 			synchronized (os) {
576: 				os.write(jsonMessage.getBytes(StandardCharsets.UTF_8));
577: 				os.write("\n".getBytes(StandardCharsets.UTF_8));
578: 				os.flush();
579: 			}
580: 			sink.next(message);
581: 		}
582: 		catch (IOException e) {
583: 			sink.error(new RuntimeException(e));
584: 		}
585: 	}
595: 	protected void handleOutbound(Function<Flux<JSONRPCMessage>, Flux<JSONRPCMessage>> outboundConsumer) {
596: 		outboundConsumer.apply(outboundSink.asFlux()).doOnComplete(() -> {
597: 			isClosing = true;
598: 			outboundSink.tryEmitComplete();
599: 		}).doOnError(e -> {
600: 			if (!isClosing) {
601: 				logger.error("Error in outbound processing", e);
602: 				this.exceptionHandler.accept(e);
603: 				isClosing = true;
604: 				outboundSink.tryEmitComplete();
605: 			}
606: 			// Logged above unless closing; not dropped to Reactor's ERROR hook.
607: 		}).subscribe(ignored -> {
608: 		}, error -> logger.debug("Outbound processing ended: {}", error.toString()));
609: 	}
622: 	@Override
623: 	public Mono<Void> closeGracefully() {
624: 		return Mono.fromRunnable(() -> {
625: 			if (!this.stopping.compareAndSet(false, true)) {
626: 				logger.debug("Already closed");
627: 				return;
628: 			}
629: 			closedLocally = true;
630: 			isClosing = true;
631: 			logger.debug("Initiating graceful shutdown");
633: 			// Complete all sinks to stop accepting new messages
634: 			inboundSink.tryEmitComplete();
635: 			outboundSink.tryEmitComplete();
636: 			errorSink.tryEmitComplete();
638: 			// Stop the process FIRST - its end closes the streams and unblocks readLine()
639: 			Process process = this.process;
640: 			if (process != null) {
641: 				stop(process);
642: 			}
644: 			// Now that process is dead and streams closed, threads should be unblocked
645: 			try {
646: 				inboundScheduler.dispose();
647: 				errorScheduler.dispose();
648: 				outboundScheduler.dispose();
649: 				logger.debug("Graceful shutdown completed");
650: 			}
651: 			catch (Exception e) {
652: 				logger.error("Error during graceful shutdown", e);
653: 			}
654: 			terminationSink.tryEmitEmpty();
655: 		});
656: 	}
663: 	private static void stop(Process process) {
664: 		try {
665: 			var stdin = process.getOutputStream();
666: 			synchronized (stdin) {
667: 				stdin.close();
668: 			}
669: 		}
670: 		catch (IOException e) {
671: 			logger.debug("Closing the agent's standard input failed: {}", e.getMessage());
672: 		}
673: 		try {
674: 			if (process.waitFor(END_OF_INPUT_WAIT_MILLIS, java.util.concurrent.TimeUnit.MILLISECONDS)) {
675: 				logExit(process.exitValue());
676: 				return;
677: 			}
678: 			logger.debug("Agent still running {} ms after the end of its input; sending TERM",
679: 					END_OF_INPUT_WAIT_MILLIS);
680: 			process.destroy();
681: 			if (process.waitFor(TERM_WAIT.toMillis(), java.util.concurrent.TimeUnit.MILLISECONDS)) {
682: 				logExit(process.exitValue());
683: 			}
684: 			else {
685: 				logger.warn("Process did not exit within timeout, forcing kill");
686: 				process.destroyForcibly();
687: 			}
688: 		}
689: 		catch (InterruptedException e) {
690: 			Thread.currentThread().interrupt();
691: 			logger.debug("Interrupted while waiting for process exit");
692: 		}
693: 	}
695: 	private static void logExit(int exitCode) {
696: 		// 143 = SIGTERM (128+15), 137 = SIGKILL (128+9) - expected when we destroy
697: 		if (exitCode == 0 || exitCode == 143 || exitCode == 137) {
698: 			logger.info("ACP agent process stopped (exit code {})", exitCode);
699: 		}
700: 		else {
701: 			logger.warn("Process terminated unexpectedly with code {}", exitCode);
702: 		}
703: 	}
713: 	@Override
714: 	public Mono<Void> awaitTermination() {
715: 		return this.terminationSink.asMono();
716: 	}
724: 	public Sinks.Many<String> getErrorSink() {
725: 		return this.errorSink;
726: 	}
728: 	@Override
729: 	public <T> T unmarshalFrom(Object data, TypeRef<T> typeRef) {
730: 		return this.jsonMapper.convertValue(data, typeRef);
731: 	}
733: }

