1: /*
5: package com.agentclientprotocol.sdk.agent.transport;
7: import java.time.Duration;
8: import java.io.BufferedReader;
9: import java.io.IOException;
10: import java.io.InputStream;
11: import java.io.InputStreamReader;
12: import java.io.OutputStream;
13: import java.nio.charset.StandardCharsets;
14: import java.util.List;
15: import java.util.Set;
16: import java.util.concurrent.ConcurrentHashMap;
17: import java.util.concurrent.Executors;
18: import java.util.concurrent.RejectedExecutionException;
19: import java.util.concurrent.atomic.AtomicBoolean;
20: import java.util.function.Consumer;
21: import java.util.function.Function;
23: import com.agentclientprotocol.sdk.error.AcpConnectionException;
24: import com.agentclientprotocol.sdk.error.AcpErrorCodes;
25: import com.agentclientprotocol.sdk.spec.AcpAgentTransport;
26: import com.agentclientprotocol.sdk.spec.AcpSchema;
27: import com.agentclientprotocol.sdk.spec.AcpSchema.JSONRPCMessage;
28: import com.agentclientprotocol.sdk.util.AcpSchedulers;
29: import com.agentclientprotocol.sdk.util.Assert;
30: import com.agentclientprotocol.sdk.util.OutboundSinks;
31: import com.agentclientprotocol.sdk.json.AcpJsonMapper;
32: import com.agentclientprotocol.sdk.json.TypeRef;
33: import org.jspecify.annotations.Nullable;
34: import org.slf4j.Logger;
35: import org.slf4j.LoggerFactory;
36: import reactor.core.Disposable;
37: import reactor.core.publisher.Mono;
38: import reactor.core.publisher.Sinks;
39: import reactor.core.publisher.SynchronousSink;
40: import reactor.core.scheduler.Scheduler;
41: import reactor.core.scheduler.Schedulers;
111: public class StdioAcpAgentTransport implements AcpAgentTransport {
113: 	private static final Logger logger = LoggerFactory.getLogger(StdioAcpAgentTransport.class);
121: 	public static final Duration DEFAULT_DRAIN_TIMEOUT = Duration.ofSeconds(60);
124: 	static final String CLIENT_INPUT_ENDED = "The ACP client closed its input; it can no longer answer requests";
126: 	private final AcpJsonMapper jsonMapper;
128: 	private final InputStream inputStream;
130: 	private final OutputStream outputStream;
132: 	private final Sinks.Many<JSONRPCMessage> inboundSink;
134: 	private final Sinks.Many<JSONRPCMessage> outboundSink;
136: 	private final Sinks.One<Void> inboundReady = Sinks.one();
138: 	private final Sinks.One<Void> outboundReady = Sinks.one();
140: 	private final Sinks.One<Void> terminationSink = Sinks.one();
142: 	private final Scheduler inboundScheduler;
144: 	private final Scheduler outboundScheduler;
146: 	private final AtomicBoolean isClosing = new AtomicBoolean(false);
148: 	private final AtomicBoolean isStarted = new AtomicBoolean(false);
150: 	private final AtomicBoolean terminated = new AtomicBoolean(false);
153: 	private final Duration drainTimeout;
156: 	private final Set<Object> awaitingAgent = ConcurrentHashMap.newKeySet();
159: 	private final UnansweredRequests awaitingClient = new UnansweredRequests();
162: 	private volatile @Nullable Function<Mono<JSONRPCMessage>, Mono<JSONRPCMessage>> handler;
164: 	private volatile @Nullable Disposable drainTimer;
166: 	private Consumer<Throwable> exceptionHandler = t -> logger.error("Transport error", t);
174: 	public StdioAcpAgentTransport() {
175: 		this(AcpJsonMapper.createDefault());
176: 	}
186: 	@SuppressWarnings("SystemOut") // the stdio transport is the one owner of System.out
187: 	public StdioAcpAgentTransport(AcpJsonMapper jsonMapper) {
188: 		this(jsonMapper, System.in, System.out);
189: 	}
200: 	public StdioAcpAgentTransport(AcpJsonMapper jsonMapper, InputStream inputStream, OutputStream outputStream) {
201: 		this(jsonMapper, inputStream, outputStream, DEFAULT_DRAIN_TIMEOUT);
202: 	}
215: 	public StdioAcpAgentTransport(AcpJsonMapper jsonMapper, InputStream inputStream, OutputStream outputStream,
216: 			Duration drainTimeout) {
217: 		Assert.notNull(jsonMapper, "The JsonMapper can not be null");
218: 		Assert.notNull(inputStream, "The InputStream can not be null");
219: 		Assert.notNull(outputStream, "The OutputStream can not be null");
220: 		Assert.notNull(drainTimeout, "The drainTimeout can not be null");
221: 		Assert.isTrue(!drainTimeout.isNegative() && !drainTimeout.isZero(), "The drainTimeout must be positive");
223: 		this.jsonMapper = jsonMapper;
224: 		this.inputStream = inputStream;
225: 		this.outputStream = outputStream;
226: 		this.drainTimeout = drainTimeout;
228: 		this.inboundSink = Sinks.many().unicast().onBackpressureBuffer();
229: 		this.outboundSink = Sinks.many().unicast().onBackpressureBuffer();
231: 		// Use daemon threads so JVM can exit if closeGracefully() isn't called
232: 		this.inboundScheduler = Schedulers.fromExecutorService(
233: 				Executors.newSingleThreadExecutor(r -> {
234: 					Thread t = new Thread(r, "acp-agent-inbound");
235: 					t.setDaemon(true);
236: 					return t;
237: 				}), "agent-inbound");
238: 		this.outboundScheduler = Schedulers.fromExecutorService(
239: 				Executors.newSingleThreadExecutor(r -> {
240: 					Thread t = new Thread(r, "acp-agent-outbound");
241: 					t.setDaemon(true);
242: 					return t;
243: 				}), "agent-outbound");
244: 	}
252: 	@Override
253: 	public Mono<Void> start(Function<Mono<JSONRPCMessage>, Mono<JSONRPCMessage>> handler) {
254: 		if (!isStarted.compareAndSet(false, true)) {
255: 			return Mono.error(new IllegalStateException("Already started"));
256: 		}
258: 		return Mono.fromRunnable(() -> {
259: 			logger.info("ACP agent transport starting");
260: 			this.handler = handler;
261: 			handleIncomingMessages(handler);
262: 			startInboundProcessing();
263: 			startOutboundProcessing();
264: 			logger.info("ACP agent transport started");
265: 		}).then(Mono.zip(inboundReady.asMono(), outboundReady.asMono()).then());
266: 	}
268: 	private void handleIncomingMessages(Function<Mono<JSONRPCMessage>, Mono<JSONRPCMessage>> handler) {
269: 		OutboundSinks.replyThrough(this.inboundSink, handler, this.outboundSink, this.inboundScheduler::dispose);
270: 	}
276: 	private void startInboundProcessing() {
277: 		this.inboundScheduler.schedule(() -> {
278: 			inboundReady.tryEmitValue(null);
279: 			try {
280: 				readMessages(new BufferedReader(new InputStreamReader(inputStream, StandardCharsets.UTF_8)));
281: 			}
282: 			catch (Exception e) {
283: 				logIfNotClosing("Error in inbound processing", e);
284: 				exceptionHandler.accept(e);
285: 			}
286: 			finally {
287: 				endInput();
288: 			}
289: 		});
290: 	}
297: 	private void endInput() {
298: 		logger.debug("Agent transport input ended");
299: 		for (Object id : this.awaitingClient.end()) {
300: 			failRequestToClient(id);
301: 		}
302: 		if (!this.isClosing.get()) {
303: 			this.drainTimer = AcpSchedulers.after(this.drainTimeout).subscribe(tick -> abandonDrain());
304: 		}
305: 		this.inboundSink.tryEmitComplete();
306: 	}
312: 	private void failRequestToClient(Object id) {
313: 		Function<Mono<JSONRPCMessage>, Mono<JSONRPCMessage>> sessionHandler = this.handler;
314: 		if (sessionHandler == null) {
315: 			return;
316: 		}
317: 		JSONRPCMessage failure = new AcpSchema.JSONRPCResponse(AcpSchema.JSONRPC_VERSION, id, null,
318: 				new AcpSchema.JSONRPCError(AcpErrorCodes.INTERNAL_ERROR, CLIENT_INPUT_ENDED, null));
319: 		Mono.just(failure)
320: 			.transform(sessionHandler)
321: 			.subscribe(reply -> logger.debug("Unexpected reply to a failed request: {}", reply),
322: 					error -> logger.debug("Failing request {} to the client failed", id, error));
323: 	}
329: 	private void abandonDrain() {
330: 		try {
331: 			this.outboundScheduler.schedule(this::cancelUnanswered);
332: 		}
333: 		catch (RejectedExecutionException e) {
334: 			logger.debug("Drain timeout after the transport terminated");
335: 		}
336: 	}
338: 	private void cancelUnanswered() {
339: 		if (this.terminated.get()) {
340: 			return;
341: 		}
342: 		this.isClosing.set(true);
343: 		logger.warn("{} request(s) received before the client closed its input are still unanswered after {};"
344: 				+ " answering them as cancelled", this.awaitingAgent.size(), this.drainTimeout);
345: 		for (Object id : List.copyOf(this.awaitingAgent)) {
346: 			if (this.awaitingAgent.remove(id)) {
347: 				writeQuietly(new AcpSchema.JSONRPCResponse(AcpSchema.JSONRPC_VERSION, id, null,
348: 						new AcpSchema.JSONRPCError(AcpErrorCodes.REQUEST_CANCELLED,
349: 								"Request cancelled: not answered within " + this.drainTimeout
350: 										+ " after the client closed its input",
351: 								null)));
352: 			}
353: 		}
354: 		terminate();
355: 		try {
356: 			this.outboundSink.emitComplete(Sinks.EmitFailureHandler.busyLooping(Duration.ofMillis(100)));
357: 		}
358: 		catch (Sinks.EmissionException e) {
359: 			logger.debug("Outbound stream already ended", e);
360: 		}
361: 	}
363: 	private void writeQuietly(JSONRPCMessage message) {
364: 		try {
365: 			writeLine(message);
366: 		}
367: 		catch (IOException e) {
368: 			logger.debug("Stream closed while cancelling unanswered requests", e);
369: 		}
370: 	}
376: 	private void terminate() {
377: 		if (!this.terminated.compareAndSet(false, true)) {
378: 			return;
379: 		}
380: 		Disposable timer = this.drainTimer;
381: 		if (timer != null) {
382: 			timer.dispose();
383: 		}
384: 		if (this.awaitingClient.ended()) {
385: 			synchronized (this.outputStream) {
386: 				try {
387: 					this.outputStream.flush();
388: 					this.outputStream.close();
389: 				}
390: 				catch (IOException e) {
391: 					logger.debug("Closing the output stream failed", e);
392: 				}
393: 			}
394: 		}
395: 		this.terminationSink.tryEmitValue(null);
396: 		logger.debug("Agent transport terminated");
397: 	}
403: 	private void readMessages(BufferedReader reader) {
404: 		boolean reading = true;
405: 		while (reading && !isClosing.get()) {
406: 			reading = readMessage(reader);
407: 		}
408: 	}
414: 	private boolean readMessage(BufferedReader reader) {
415: 		String line;
416: 		try {
417: 			line = reader.readLine();
