25: 		private final AtomicBoolean cancelled = new AtomicBoolean();
27: 		private final Sinks.Empty<Void> sink = Sinks.empty();
30: 		void cancel() {
31: 			if (this.cancelled.compareAndSet(false, true)) {
32: 				this.sink.tryEmitEmpty();
33: 			}
34: 		}
36: 		boolean isCancelled() {
37: 			return this.cancelled.get();
38: 		}
40: 		Mono<Void> whenCancelled() {
41: 			return this.sink.asMono();
42: 		}
44: 	}
46: 	private final ConcurrentHashMap<String, Signal> active = new ConcurrentHashMap<>();
52: 	Signal start(String sessionId) {
53: 		Signal signal = new Signal();
54: 		this.active.put(sessionId, signal);
55: 		return signal;
56: 	}
59: 	void end(String sessionId, Signal signal) {
60: 		this.active.remove(sessionId, signal);
61: 	}
64: 	void cancel(@Nullable String sessionId) {
65: 		if (sessionId == null) {
66: 			return;
67: 		}
68: 		Signal signal = this.active.get(sessionId);
69: 		if (signal != null) {
70: 			signal.cancel();
71: 		}
72: 	}
